    try {
        if ($script:sync.WPFConsoleOutput) {
            $script:sync.WPFConsoleOutput.Text = "Windows PowerShell Console`r`nCopyright (C) Microsoft Corporation. All rights reserved.`r`n`r`nPS C:\> "
        }
        Update-ConsoleStatus "Console cleared"
        Write-Logger "Console output cleared" "DEBUG"
    }
    catch { Write-Logger "Error clearing console output: $($_.Exception.Message)" "ERROR" }
}

function Update-ConsoleStatus {
    param([string]$Status)
    try {
        if ($script:sync.WPFConsoleStatus) {
            $action = { $script:sync.WPFConsoleStatus.Text = $Status }
            if ($script:sync.Form.Dispatcher.CheckAccess()) { & $action }
            else { $script:sync.Form.Dispatcher.BeginInvoke([System.Action]$action) | Out-Null }
        }
    }
    catch { Write-Logger "Error updating console status: $($_.Exception.Message)" "ERROR" }
}

function Navigate-CommandHistory {
    param([string]$Direction)
    try {
        $history = $script:ConsoleState.CommandHistory
        if ($history.Count -eq 0) { return }
        if ($Direction -eq "Up"   -and $script:ConsoleState.HistoryIndex -lt ($history.Count - 1)) { $script:ConsoleState.HistoryIndex++ }
        if ($Direction -eq "Down" -and $script:ConsoleState.HistoryIndex -gt -1) { $script:ConsoleState.HistoryIndex-- }
        if ($script:ConsoleState.HistoryIndex -ge 0) {
            $cmd = $history[$history.Count-1-$script:ConsoleState.HistoryIndex]
            $script:sync.WPFConsoleInput.Text = $cmd
            $script:sync.WPFConsoleInput.CaretIndex = $cmd.Length
        } else { $script:sync.WPFConsoleInput.Text = "" }
    }
    catch { Write-Logger "Error navigating command history: $($_.Exception.Message)" "ERROR" }
}

function Stop-ConsoleCommand {
    try {
        if ($script:ConsoleState.IsRunning) {
            Write-Logger "Stopping console command" "WARNING"
            try {
                $script:ConsoleState.CurrentCommand.PowerShell.Stop()
                Add-ConsoleOutput "Command stopped by user" "Warning"
            }
            catch { Add-ConsoleOutput "Error stopping command: $($_.Exception.Message)" "Error" }
            finally { Complete-ConsoleExecution }
        }
        else { Add-ConsoleOutput "No command currently running" "Info" }
    }
    catch { Write-Logger "Error stopping console command: $($_.Exception.Message)" "ERROR" }
}

function Close-WDCAConsole {
    try {
        Write-Logger "Closing WDCA console..." "INFO"
        if ($script:ConsoleState.IsRunning) { Complete-ConsoleExecution }
        if ($script:ConsoleRunspace) {
            try { $script:ConsoleRunspace.Close(); $script:ConsoleRunspace.Dispose(); $script:ConsoleRunspace=$null }
            catch { Write-Logger "Error closing console runspace: $($_.Exception.Message)" "WARNING" }
        }
        Write-Logger "Console closed and cleaned up" "INFO"
    }
    catch { Write-Logger "Error closing console: $($_.Exception.Message)" "ERROR" }
}



function Set-WDCATheme {
    <#
    .SYNOPSIS
        Applies a theme to the WDCA application

    .PARAMETER ThemeName
        Name of the theme to apply (Dark, Light)
    #>

    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet("Dark", "Light")]
        [string]$ThemeName
    )

    if (-not $global:WDCAThemes) {
        Initialize-ThemeManager
    }

    $theme = $global:WDCAThemes[$ThemeName]

    if (-not $theme) {
        Write-Logger "Theme '$ThemeName' not found" "ERROR"
        return
    }

    try {
        Write-Logger "Applying theme: $ThemeName" "INFO"

        # Update resource dictionary with new theme colors
        if ($global:sync.Form -and $global:sync.Form.Resources) {
            $resources = $global:sync.Form.Resources

            # Update color resources
            foreach ($colorName in $theme.Keys) {
                # Skip non-color properties
                if ($colorName -like "*Opacity" -or $colorName -like "*Radius" -or $colorName -like "*Thickness") {
                    continue
                }

                $resourceKey = "${colorName}Brush"
                $colorValue = $theme[$colorName]

                try {
                    $brush = New-Object System.Windows.Media.SolidColorBrush
                    $brush.Color = [System.Windows.Media.ColorConverter]::ConvertFromString($colorValue)

                    if ($resources.Contains($resourceKey)) {
                        $resources[$resourceKey] = $brush
                    } else {
                        $resources.Add($resourceKey, $brush)
                    }
                }
                catch {
                    Write-Logger "Error setting color resource $resourceKey`: $($_.Exception.Message)" "DEBUG"
                }
            }

            Write-Logger "Theme '$ThemeName' applied successfully" "INFO"
        }
    }
    catch {
        Write-Logger "Error applying theme '$ThemeName': $($_.Exception.Message)" "ERROR"
    }
}

function Update-UI {
    <#
    .SYNOPSIS
        Thread-sichere UI-Updates (vereinfacht)
    #>
    param(
        [string]$Status = "",
        [int]$Progress = -1,
        [bool]$EnableButtons = $true
    )

    if (-not $global:sync.Form) { return }

    try {
        $global:sync.Form.Dispatcher.Invoke([action]{
            # Status aktualisieren
            if ($Status -and $global:sync.WPFStatusText) {
                $global:sync.WPFStatusText.Text = $Status
            }

            # Progress aktualisieren
            if ($global:sync.WPFProgressBar) {
                if ($Progress -ge 0 -and $Progress -le 100) {
                    $global:sync.WPFProgressBar.Value = $Progress
                    $global:sync.WPFProgressBar.IsIndeterminate = $false
                    $global:sync.WPFProgressBar.Visibility = "Visible"
                } elseif ($Progress -eq -1) {
                    $global:sync.WPFProgressBar.IsIndeterminate = $true
                    $global:sync.WPFProgressBar.Visibility = "Visible"
                } else {
                    $global:sync.WPFProgressBar.Visibility = "Collapsed"
                }
            }

            # Buttons aktivieren/deaktivieren
            $buttonNames = @(
                "WPFInstallSelectedApps", "WPFSelectAllApps", "WPFDeselectAllApps",
                "WPFConfigureNetwork", "WPFEnableRDP", "WPFRunDiagnostics",
                "WPFRunDISM", "WPFRunSFC", "WPFRunCHKDSK", "WPFUpdateApps",
                "WPFRunCleanup", "WPFRefreshDebloatList", "WPFUninstallSelected"
            )

            foreach ($buttonName in $buttonNames) {
                if ($global:sync[$buttonName]) {
                    $global:sync[$buttonName].IsEnabled = $EnableButtons
                }
            }
        })
    }
    catch {
        Write-Logger "UI update error: $($_.Exception.Message)" "ERROR"
    }
}

function Initialize-WDCAConsole {
    try {
        Write-Logger "Initializing console" "INFO"

        $global:ConsoleRunspace = [runspacefactory]::CreateRunspace()
        $global:ConsoleRunspace.Open()

        $global:ConsoleState = @{
            IsVisible = $false; IsRunning = $false; CommandHistory = @()
        }

        # Event handlers setzen
        if ($global:sync.WPFToggleConsole) {
            $global:sync.WPFToggleConsole.Add_Click({ Toggle-Console })
        }

        if ($global:sync.WPFClearConsole) {
            $global:sync.WPFClearConsole.Add_Click({ Clear-Console })
        }

        if ($global:sync.WPFExecuteCommand) {
            $global:sync.WPFExecuteCommand.Add_Click({ Execute-ConsoleCommand })
        }

        if ($global:sync.WPFConsoleInput) {
            $global:sync.WPFConsoleInput.Add_KeyDown({
                param($sender, $e)
                if ($e.Key -eq "Return") { Execute-ConsoleCommand }
            })
        }

        Write-Logger "Console initialized" "SUCCESS"
    }
    catch {
        Write-Logger "Console init error: $($_.Exception.Message)" "ERROR"
    }
}

function Add-ConsoleOutput {
    param([string]$Text, [string]$Type = "Output")

    if (-not $global:sync.WPFConsoleOutput) { return }

    try {
        $timestamp = Get-Date -Format "HH:mm:ss"
        $formattedText = "[$timestamp] $Text`r`n"

        if ($global:sync.Form.Dispatcher.CheckAccess()) {
            $global:sync.WPFConsoleOutput.AppendText($formattedText)
        } else {
            $global:sync.Form.Dispatcher.Invoke([action]{
                $global:sync.WPFConsoleOutput.AppendText($formattedText)
            })
        }
    }
    catch { }
}

function Clear-Console {
    if ($global:sync.WPFConsoleOutput) {
        $global:sync.WPFConsoleOutput.Text = "PowerShell Console`r`nPS C:\> "
    }
}



function Get-SystemThemePreference {
    <#
    .SYNOPSIS
        Detects the system's current theme preference
    #>

    try {
        $appsUseLightTheme = Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "AppsUseLightTheme" -ErrorAction SilentlyContinue

        if ($appsUseLightTheme -and $appsUseLightTheme.AppsUseLightTheme -eq 1) {
            return "Light"
        } else {
            return "Dark"
        }
    }
    catch {
        Write-Logger "Could not detect system theme preference, defaulting to Dark" "WARNING"
        return "Dark"
    }
}

function Initialize-WDCAApplications {
    <#
    .SYNOPSIS
        Initializes the applications panel with modern UI
    #>

    try {
        if (-not $global:sync.configs.applications) {
            Write-Logger "No applications configuration found" "WARNING"
            return
        }

        if (-not $global:sync.WPFApplicationsPanel) {
            Write-Logger "Applications panel not found in UI" "WARNING"
            return
        }

        Write-Logger "Populating applications panel..." "INFO"

        $appsPanel = $global:sync.WPFApplicationsPanel
        $appsCreated = 0

        # Clear existing content
        $appsPanel.Children.Clear() | Out-Null

        # Group applications by category
        $categories = $global:sync.configs.applications.PSObject.Properties |
            Group-Object { $_.Value.category } |
            Sort-Object Name

        foreach ($category in $categories) {
            # Create category card
            $categoryCard = New-Object System.Windows.Controls.Border
            if ($global:sync.Form.Resources["ModernCard"]) {
                $categoryCard.Style = $global:sync.Form.Resources["ModernCard"]
            } else {
                # Fallback styling
                $categoryCard.Background = [System.Windows.Media.Brushes]::DarkGray
                $categoryCard.CornerRadius = "8"
                $categoryCard.Padding = "16"
                $categoryCard.Margin = "0,0,0,16"
            }

            $categoryStack = New-Object System.Windows.Controls.StackPanel

            # Category header
            $categoryLabel = New-Object System.Windows.Controls.TextBlock
            $categoryLabel.Text = $category.Name
            $categoryLabel.FontWeight = "Bold"
            $categoryLabel.FontSize = 16
            $categoryLabel.Margin = "0,0,0,12"
            $categoryLabel.Foreground = [System.Windows.Media.Brushes]::White
            $categoryStack.Children.Add($categoryLabel) | Out-Null

            # Add applications in this category
            foreach ($app in ($category.Group | Sort-Object { $_.Value.content })) {
                # Create checkbox
                $checkbox = New-Object System.Windows.Controls.CheckBox
                $checkboxName = $app.Name  # Already has WPFInstall prefix
                $checkbox.Name = $checkboxName
                $checkbox.Content = $app.Value.content
                $checkbox.ToolTip = $app.Value.description
                $checkbox.Margin = "0,0,0,8"
                $checkbox.Foreground = [System.Windows.Media.Brushes]::White
                $checkbox.FontSize = 12

                # Apply modern style if available
                if ($global:sync.Form.Resources["FluentCheckBox"]) {
                    $checkbox.Style = $global:sync.Form.Resources["FluentCheckBox"]
                }

                $categoryStack.Children.Add($checkbox) | Out-Null

                # Store reference in sync hashtable
                $global:sync[$checkboxName] = $checkbox
                $appsCreated++
            }

            $categoryCard.Child = $categoryStack
            $appsPanel.Children.Add($categoryCard) | Out-Null
        }
    }
    catch {
        Write-Logger "Error initializing applications: $($_.Exception.Message)" "ERROR"
        Write-Host "Detailed error: $($_.Exception)" -ForegroundColor Red
    }
}


