function Convert-SubnetMaskToPrefixLength {
    param([string]$SubnetMask)
    try {
        $mask = [System.Net.IPAddress]::Parse($SubnetMask)
        $bytes = $mask.GetAddressBytes()
        $binaryString = ""

        # Convert all bytes to binary string
        foreach ($byte in $bytes) {
            $binaryString += [Convert]::ToString($byte, 2).PadLeft(8, '0')
        }

        # Count consecutive 1s from the left
        $prefixLength = 0
        for ($i = 0; $i -lt $binaryString.Length; $i++) {
            if ($binaryString[$i] -eq '1') {
                $prefixLength++
            } else {
                break
            }
        }

        # Validate that all remaining bits are 0
        $remainingBits = $binaryString.Substring($prefixLength)
        if ($remainingBits -match '1') {
            throw "Invalid subnet mask - non-contiguous bits"
        }

        return $prefixLength
    }
    catch {
        Write-Logger "Error converting subnet mask '$SubnetMask': $($_.Exception.Message)" "WARNING"
        return 24  # Default to /24
    }
}

function Initialize-DebloatApplications {
    try {
        Write-Logger "Initializing debloat applications panel..." "INFO"

        if (-not $global:sync.WPFDebloatPanel) {
            Write-Logger "Debloat panel not found in UI" "ERROR"
            return
        }

        $global:sync.WPFDebloatPanel.Children.Clear()

        # Loading indicator
        $loadingBorder = New-Object System.Windows.Controls.Border
        $loadingBorder.Style = $global:sync.Form.Resources["ModernCard"]

        $loadingStack = New-Object System.Windows.Controls.StackPanel
        $loadingText = New-Object System.Windows.Controls.TextBlock
        $loadingText.Text = "Scanning installed applications..."
        $loadingText.FontSize = 14
        $loadingText.Foreground = [System.Windows.Media.Brushes]::White
        $loadingText.HorizontalAlignment = "Center"

        $loadingStack.Children.Add($loadingText)
        $loadingBorder.Child = $loadingStack
        $global:sync.WPFDebloatPanel.Children.Add($loadingBorder)

        Write-Logger "Scanning installed applications..." "INFO"
        $applications = @()

        # --------------------------
        # Method 1: UWP Applications
        # --------------------------
        if ($PSVersionTable.PSVersion.Major -eq 5) {
            try {
                if (Get-Module -ListAvailable -Name Appx) {
                    Import-Module Appx -Force -ErrorAction Stop
                    Write-Logger "Scanning UWP applications..." "INFO"

                    $currentUserUwp = Get-AppxPackage | Where-Object {
                        $_.Name -and
                        $_.PackageFullName -and
                        $_.Name -notlike "Microsoft.Windows*" -and
                        $_.Name -notlike "Microsoft.VCRedist*" -and
                        $_.Name -notlike "*Framework*" -and
                        $_.Name -notlike "*VCLibs*" -and
                        $_.Name -notlike "Microsoft.NET*" -and
                        $_.Name -notlike "Microsoft.UI*" -and
                        $_.Name -notlike "Microsoft.Services*" -and
                        $_.Name -notlike "Microsoft.DesktopApp*" -and
                        $_.Name -notlike "*InputApp*" -and
                        $_.PublisherId -ne "cw5n1h2txyewy"
                    }

                    $provisionedApps = Get-AppxProvisionedPackage -Online | Where-Object {
                        $_.DisplayName -and
                        $_.DisplayName -notlike "Microsoft.Windows*" -and
                        $_.DisplayName -notlike "*Framework*" -and
                        $_.DisplayName -notlike "*VCLibs*"
                    }

                    $allUwpApps = @{}

                    foreach ($app in $currentUserUwp) {
                        $key = $app.Name
                        if (-not $allUwpApps.ContainsKey($key)) {
                            $displayName = if ($app.DisplayName) { $app.DisplayName } else { $app.Name }
                            $publisher = if ($app.Publisher) { $app.Publisher } else { "Unknown" }
                            $allUwpApps[$key] = [PSCustomObject]@{
                                Name            = $app.Name
                                DisplayName     = $displayName
                                Version         = $app.Version.ToString()
                                Publisher       = $publisher
                                Type            = "UWP"
                                PackageFullName = $app.PackageFullName
                                Size            = 0
                                IsProvisioned   = $false
                            }
                        }
                    }

                    foreach ($app in $provisionedApps) {
                        $key = $app.DisplayName
                        if (-not $allUwpApps.ContainsKey($key)) {
                            $allUwpApps[$key] = [PSCustomObject]@{
                                Name            = $app.DisplayName
                                DisplayName     = $app.DisplayName
                                Version         = $app.Version
                                Publisher       = "Microsoft Store"
                                Type            = "UWP"
                                PackageFullName = $app.PackageName
                                Size            = 0
                                IsProvisioned   = $true
                            }
                        }
                    }

                    $applications += $allUwpApps.Values
                    Write-Logger "Found $($allUwpApps.Count) UWP applications" "INFO"
                }
                else {
                    Write-Logger "Appx module not available – skipping UWP scan" "WARNING"
                }
            }
            catch {
                $msg = ($_ | Out-String).Split("`n")[0]
                Write-Logger "Error scanning UWP apps: $msg" "WARNING"
            }
        }
        else {
            Write-Logger "Skipping UWP scan (requires Windows PowerShell 5.1)" "INFO"
        }

        # --------------------------
        # Method 2: Win32 Applications
        # --------------------------
        try {
            Write-Logger "Scanning Win32 applications..." "INFO"
            $registryPaths = @(
                'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
                'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
                'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
            )

            $win32Apps = @()
            foreach ($path in $registryPaths) {
                $pathApps = Get-ItemProperty -Path $path -ErrorAction SilentlyContinue | Where-Object {
                    $_.DisplayName -and
                    $_.UninstallString -and
                    $_.SystemComponent -ne 1 -and
                    $_.WindowsInstaller -ne 1 -and
                    $_.ParentKeyName -eq $null -and
                    $_.DisplayName -notlike "*Hotfix*" -and
                    $_.DisplayName -notlike "*Security Update*" -and
                    $_.DisplayName -notlike "Update for*"
                }
                $win32Apps += $pathApps
            }

            $processedNames = @{}
            foreach ($app in $win32Apps) {
                $key = $app.DisplayName
                if ($processedNames.ContainsKey($key)) { continue }
                $processedNames[$key] = $true

                $size = 0
                if ($app.EstimatedSize) {
                    $size = [math]::Round($app.EstimatedSize / 1024, 2)
                }

                $applications += [PSCustomObject]@{
                    Name            = $app.DisplayName
                    DisplayName     = $app.DisplayName
                    Version         = if ($app.DisplayVersion) { $app.DisplayVersion } else { "Unknown" }
                    Publisher       = if ($app.Publisher) { $app.Publisher } else { "Unknown" }
                    Type            = "Win32"
                    PackageFullName = $app.UninstallString
                    Size            = $size
                    IsProvisioned   = $false
                }
            }
            Write-Logger "Found $($processedNames.Count) unique Win32 applications" "INFO"
        }
        catch {
            $msg = ($_ | Out-String).Split("`n")[0]
            Write-Logger "Error scanning Win32 apps: $msg" "WARNING"
        }

        # --------------------------
        # Method 3: MSI Apps via CIM
        # --------------------------
        try {
            Write-Logger "Scanning MSI applications via CIM..." "INFO"
            $cimApps = Get-CimInstance -ClassName Win32_Product -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -and
                $_.Name -notlike "*Update*" -and
                $_.Name -notlike "*Hotfix*" -and
                $_.Name -notlike "*Security Update*"
            }

            $cimAppNames = $applications | ForEach-Object { $_.DisplayName }

            foreach ($app in $cimApps) {
                if ($app.Name -notin $cimAppNames) {
                    $applications += [PSCustomObject]@{
                        Name            = $app.Name
                        DisplayName     = $app.Name
                        Version         = if ($app.Version) { $app.Version } else { "Unknown" }
                        Publisher       = if ($app.Vendor) { $app.Vendor } else { "Unknown" }
                        Type            = "MSI"
                        PackageFullName = $app.IdentifyingNumber
                        Size            = 0
                        IsProvisioned   = $false
                    }
                }
            }
            Write-Logger "Found $($cimApps.Count) additional MSI applications" "INFO"
        }
        catch {
            $msg = ($_ | Out-String).Split("`n")[0]
            Write-Logger "Error scanning CIM apps: $msg" "WARNING"
        }

        # --------------------------
        # Finalize & Update UI
        # --------------------------
        $uniqueApps = @{}
        $finalApplications = @()
        foreach ($app in $applications) {
            $key = $app.DisplayName.ToLower()
            if (-not $uniqueApps.ContainsKey($key)) {
                $uniqueApps[$key] = $true
                $finalApplications += $app
            }
        }

        Write-Logger "Total unique applications found: $($finalApplications.Count)" "INFO"
        $sortedApplications = $finalApplications | Sort-Object DisplayName
        Update-DebloatUI -Applications $sortedApplications
    }
    catch {
        Write-Logger "Error initializing debloat applications: $($_.Exception.Message)" "ERROR"
        $global:sync.WPFDebloatPanel.Children.Clear()

        $errorBorder = New-Object System.Windows.Controls.Border
        $errorBorder.Style = $global:sync.Form.Resources["ModernCard"]

        $errorStack = New-Object System.Windows.Controls.StackPanel
        $errorText = New-Object System.Windows.Controls.TextBlock
        $errorText.Text = "Error loading applications: $($_.Exception.Message)"
        $errorText.FontSize = 12
        $errorText.Foreground = [System.Windows.Media.Brushes]::Red
        $errorText.TextWrapping = "Wrap"

        $errorStack.Children.Add($errorText)
        $errorBorder.Child = $errorStack
        $global:sync.WPFDebloatPanel.Children.Add($errorBorder)
    }
}

function Invoke-DebloatUninstall {
    Write-Logger "Starting application uninstallation..." "INFO"

    # Collect selected applications
    $selectedApps = @()
    $global:sync.WPFDebloatPanel.Children | ForEach-Object {
        if ($_.Child -is [System.Windows.Controls.StackPanel]) {
            $_.Child.Children | ForEach-Object {
                if ($_ -is [System.Windows.Controls.ScrollViewer]) {
                    $_.Content.Children | ForEach-Object {
                        if ($_ -is [System.Windows.Controls.Grid]) {
                            $checkbox = $_.Children | Where-Object { $_ -is [System.Windows.Controls.CheckBox] }
                            if ($checkbox -and $checkbox.IsChecked -and $checkbox.Tag) {
                                $selectedApps += $checkbox.Tag
                            }
                        }
                    }
                }
            }
        }
    }

    if ($selectedApps.Count -eq 0) {
        [System.Windows.MessageBox]::Show("No applications selected for uninstallation.", "WDCA", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
        return
    }

    # Single confirmation for all apps
    $appList = ($selectedApps | ForEach-Object { "• $($_.DisplayName)" }) -join "`n"
    $result = [System.Windows.MessageBox]::Show(
        "Uninstall these $($selectedApps.Count) applications?`n`n$appList`n`nThis will proceed automatically without further prompts.",
        "WDCA - Confirm Uninstallation",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question
    )
    if ($result -ne [System.Windows.MessageBoxResult]::Yes) { return }

    # Start uninstallation directly in background
    Write-Logger "Starting silent uninstallation of $($selectedApps.Count) applications..." "INFO"

    $successCount = 0
    $errorCount = 0

    foreach ($app in $selectedApps) {
        try {
            Write-Logger "Uninstalling: $($app.DisplayName)" "INFO"

            if ($app.Type -eq "UWP") {
                # UWP app
                Remove-AppxPackage -Package $app.PackageFullName -ErrorAction Stop
                Write-Logger "Successfully removed UWP app: $($app.DisplayName)" "SUCCESS"
                $successCount++
            }
            else {
                # Win32 app
                $uninstallCmd = $app.PackageFullName

                if ($uninstallCmd -like "*msiexec*") {
                    # MSI Package
                    if ($uninstallCmd -match '{[A-F0-9\-]+}') {
                        $productCode = $matches[0]
                        Write-Logger "Uninstalling MSI package: $productCode" "INFO"
                        Start-Process -FilePath 'msiexec.exe' -ArgumentList '/x', $productCode, '/quiet', '/norestart' -Wait -NoNewWindow
                        Write-Logger "Successfully uninstalled MSI package: $($app.DisplayName)" "SUCCESS"
                        $successCount++
                    }
                    else {
                        throw "Could not extract MSI product code"
                    }
                }
                else {
                    # Generic uninstaller
                    try {
                        # Versuch: Executable + Argumente extrahieren
                        if ($uninstallCmd -match '^"(.+?)"(.*)') {
                            $exePath = $matches[1]
                            $arguments = $matches[2].Trim()

                            if ($arguments -and $arguments -notmatch '/S|/silent|/quiet') {
                                $arguments += ' /S'
                            }
                            elseif (-not $arguments) {
                                $arguments = '/S'
                            }

                            if ($arguments) {
                                Start-Process -FilePath $exePath -ArgumentList ($arguments -split ' ' | Where-Object { $_ }) -Wait -NoNewWindow
                            }
                            else {
                                Start-Process -FilePath $exePath -Wait -NoNewWindow
                            }
                        }
                        else {
                            # Direktes Command
                            if ($uninstallCmd -notmatch '/S|/silent|/quiet') {
                                $uninstallCmd += ' /S'
                            }
                            Start-Process -FilePath 'cmd.exe' -ArgumentList @('/c', $uninstallCmd) -Wait -NoNewWindow
                        }

                        Write-Logger "Successfully uninstalled application: $($app.DisplayName)" "SUCCESS"
                        $successCount++
                    }
                    catch {
                        Write-Logger "Error uninstalling application $($app.DisplayName): $($_.Exception.Message)" "ERROR"
                    }
                }

            }
        }
        catch {
            Write-Logger "Failed to uninstall $($app.DisplayName): $($_.Exception.Message)" "ERROR"
            $errorCount++
        }
    }

    # Show final summary
    $summaryMessage = "Uninstallation completed.`n`n"
    $summaryMessage += "Successfully uninstalled: $successCount`n"
    $summaryMessage += "Failed: $errorCount`n"
    $summaryMessage += "Total processed: $($selectedApps.Count)"

    if ($successCount -eq $selectedApps.Count) {
        $icon = [System.Windows.MessageBoxImage]::Information
        $title = "WDCA - Success"
    }
    elseif ($successCount -gt 0) {
        $icon = [System.Windows.MessageBoxImage]::Warning
        $title = "WDCA - Partial Success"
    }
    else {
        $icon = [System.Windows.MessageBoxImage]::Error
        $title = "WDCA - Failed"
    }

    [System.Windows.MessageBox]::Show($summaryMessage, $title, [System.Windows.MessageBoxButton]::OK, $icon)

    # Refresh the application list
    Initialize-DebloatApplications
}

function Update-DebloatUI {
    param([array]$Applications)

    try {
        Write-Logger "Updating debloat UI with $($Applications.Count) applications..." "INFO"

        $global:sync.WPFDebloatPanel.Children.Clear()

        if (-not $Applications -or $Applications.Count -eq 0) {
            $noAppsBorder = New-Object System.Windows.Controls.Border
            $noAppsBorder.Style = $global:sync.Form.Resources["ModernCard"]

            $noAppsText = New-Object System.Windows.Controls.TextBlock
            $noAppsText.Text = "No applications found for removal."
            $noAppsText.Foreground = [System.Windows.Media.Brushes]::Gray
            $noAppsText.HorizontalAlignment = "Center"

            $noAppsBorder.Child = $noAppsText
            $global:sync.WPFDebloatPanel.Children.Add($noAppsBorder)
            return
        }

        $mainBorder = New-Object System.Windows.Controls.Border
        $mainBorder.Style = $global:sync.Form.Resources["ModernCard"]

        $mainStack = New-Object System.Windows.Controls.StackPanel

        # Header with statistics
        $headerText = New-Object System.Windows.Controls.TextBlock
        $headerText.Text = "Installed Applications"
        $headerText.FontWeight = "Bold"
        $headerText.FontSize = 16
        $headerText.Foreground = [System.Windows.Media.Brushes]::White
        $mainStack.Children.Add($headerText)

        $uwpCount = ($Applications | Where-Object { $_.Type -eq "UWP" }).Count
        $win32Count = ($Applications | Where-Object { $_.Type -eq "Win32" }).Count

        $statsText = New-Object System.Windows.Controls.TextBlock
        $statsText.Text = "Total: $($Applications.Count) | UWP: $uwpCount | Win32: $win32Count"
        $statsText.FontSize = 11
        $statsText.Foreground = [System.Windows.Media.Brushes]::Gray
        $statsText.Margin = "0,2,0,10"
        $mainStack.Children.Add($statsText)

        # Control buttons
        $buttonStack = New-Object System.Windows.Controls.StackPanel
        $buttonStack.Orientation = "Horizontal"
        $buttonStack.Margin = "0,0,0,10"

        $selectAllBtn = New-Object System.Windows.Controls.Button
        $selectAllBtn.Content = "Select All"
        $selectAllBtn.Style = $global:sync.Form.Resources["FluentButtonSecondary"]
        $selectAllBtn.Margin = "0,0,10,0"

        $deselectAllBtn = New-Object System.Windows.Controls.Button
        $deselectAllBtn.Content = "Deselect All"
        $deselectAllBtn.Style = $global:sync.Form.Resources["FluentButtonSecondary"]

        $buttonStack.Children.Add($selectAllBtn)
        $buttonStack.Children.Add($deselectAllBtn)
        $mainStack.Children.Add($buttonStack)

        # Applications list
        $scrollViewer = New-Object System.Windows.Controls.ScrollViewer
        $scrollViewer.Height = 500
        $scrollViewer.VerticalScrollBarVisibility = "Auto"

        $appsStack = New-Object System.Windows.Controls.StackPanel
        $allCheckboxes = @()

        foreach ($app in $Applications) {
            $appGrid = New-Object System.Windows.Controls.Grid
            $appGrid.Margin = "0,2,0,2"

            # Grid columns
            $col1 = New-Object System.Windows.Controls.ColumnDefinition
            $col1.Width = "Auto"
            $col2 = New-Object System.Windows.Controls.ColumnDefinition
            $col2.Width = "*"
            $col3 = New-Object System.Windows.Controls.ColumnDefinition
            $col3.Width = "Auto"

            $appGrid.ColumnDefinitions.Add($col1)
            $appGrid.ColumnDefinitions.Add($col2)
            $appGrid.ColumnDefinitions.Add($col3)

            # Checkbox
            $checkbox = New-Object System.Windows.Controls.CheckBox
            $checkbox.Style = $global:sync.Form.Resources["FluentCheckBox"]
            $checkbox.Tag = $app
            $checkbox.VerticalAlignment = "Center"
            $checkbox.Margin = "0,0,10,0"
            [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)

            # App info
            $infoStack = New-Object System.Windows.Controls.StackPanel

            $nameText = New-Object System.Windows.Controls.TextBlock
            $nameText.Text = $app.DisplayName
            $nameText.FontWeight = "Medium"
            $nameText.FontSize = 13
            $nameText.Foreground = [System.Windows.Media.Brushes]::White

            $detailText = New-Object System.Windows.Controls.TextBlock
            $detailText.Text = "Version: $($app.Version) | Publisher: $($app.Publisher)"
            if ($app.Size -gt 0) {
                $detailText.Text += " | Size: $($app.Size) MB"
            }
            $detailText.FontSize = 10
            $detailText.Foreground = [System.Windows.Media.Brushes]::Gray

            $infoStack.Children.Add($nameText)
            $infoStack.Children.Add($detailText)
            [System.Windows.Controls.Grid]::SetColumn($infoStack, 1)

            # Type badge
            $typeBadge = New-Object System.Windows.Controls.Border
            $typeBadge.CornerRadius = 3
            $typeBadge.Padding = "6,2"

            if ($app.Type -eq "UWP") {
                $typeBadge.Background = [System.Windows.Media.Brushes]::DarkBlue
            }
            else {
                $typeBadge.Background = [System.Windows.Media.Brushes]::DarkOrange
            }

            $typeText = New-Object System.Windows.Controls.TextBlock
            $typeText.Text = $app.Type
            $typeText.FontSize = 10
            $typeText.FontWeight = "Bold"
            $typeText.Foreground = [System.Windows.Media.Brushes]::White

            $typeBadge.Child = $typeText
            [System.Windows.Controls.Grid]::SetColumn($typeBadge, 2)

            $appGrid.Children.Add($checkbox)
            $appGrid.Children.Add($infoStack)
            $appGrid.Children.Add($typeBadge)
            $appsStack.Children.Add($appGrid)

            $allCheckboxes += $checkbox
        }

        # Wire up button events
        $selectAllBtn.Add_Click({
                foreach ($cb in $allCheckboxes) {
                    $cb.IsChecked = $true
                }
            }.GetNewClosure())

        $deselectAllBtn.Add_Click({
                foreach ($cb in $allCheckboxes) {
                    $cb.IsChecked = $false
                }
            }.GetNewClosure())

        $scrollViewer.Content = $appsStack
        $mainStack.Children.Add($scrollViewer)
        $mainBorder.Child = $mainStack
        $global:sync.WPFDebloatPanel.Children.Add($mainBorder)

        Write-Logger "Successfully populated debloat UI with $($Applications.Count) applications" "SUCCESS"

    }
    catch {
        Write-Logger "Error updating debloat UI: $($_.Exception.Message)" "ERROR"
    }
}

function Invoke-NetworkConfiguration {
    <#
    .SYNOPSIS
        Configures network settings
    .DESCRIPTION
        Sets IP address, subnet mask, gateway, DNS servers, IPv6 settings, or enables DHCP
    #>
    Write-Logger "Configuring network settings" "INFO"

    # Get values from UI
    $useDHCP = if ($sync.WPFDHCP) { $sync.WPFDHCP.IsChecked } else { $false }
    $useStaticIP = if ($sync.WPFStaticIP) { $sync.WPFStaticIP.IsChecked } else { $true }
    $ipAddress = if ($sync.WPFNetworkIP) { $sync.WPFNetworkIP.Text.Trim() } else { "" }
    $subnetMask = if ($sync.WPFNetworkSubnet) { $sync.WPFNetworkSubnet.Text.Trim() } else { "" }
    $gateway = if ($sync.WPFNetworkGateway) { $sync.WPFNetworkGateway.Text.Trim() } else { "" }
    $dnsServer = if ($sync.WPFNetworkDNS) { $sync.WPFNetworkDNS.Text.Trim() } else { "" }
    $dnsAltServer = if ($sync.WPFNetworkDNSAlt) { $sync.WPFNetworkDNSAlt.Text.Trim() } else { "" }
    $disableIPv6 = if ($sync.WPFDisableIPv6) { $sync.WPFDisableIPv6.IsChecked } else { $false }

    # Validate input for Static IP
    if ($useStaticIP -and [string]::IsNullOrEmpty($ipAddress)) {
        Write-Logger "IP Address is required for static IP configuration" "ERROR"
        [System.Windows.MessageBox]::Show("Please enter an IP address for static configuration.", "WDCA - Network Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning)
        return
    }

    # Validate IP address format for Static IP
    if ($useStaticIP) {
        try {
            [System.Net.IPAddress]::Parse($ipAddress) | Out-Null
        }
        catch {
            Write-Logger "Invalid IP address format: $ipAddress" "ERROR"
            [System.Windows.MessageBox]::Show("Please enter a valid IP address.", "WDCA - Network Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning)
            return
        }
    }

    try {
        # Get the primary network adapter
        $adapter = Get-NetAdapter | Where-Object { $_.Status -eq "Up" -and $_.InterfaceType -eq 6 } | Select-Object -First 1
        if (-not $adapter) {
            Write-Logger "No active network adapter found" "ERROR"
            [System.Windows.MessageBox]::Show("No active network adapter found.", "WDCA - Network Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
            return
        }

        Write-Logger "Configuring adapter: $($adapter.Name)" "INFO"

        if ($useDHCP) {
            # Configure DHCP
            Write-Logger "Enabling DHCP configuration" "INFO"

            # Remove existing static IP configuration
            Remove-NetIPAddress -InterfaceAlias $adapter.Name -Confirm:$false -ErrorAction SilentlyContinue
            Remove-NetRoute -InterfaceAlias $adapter.Name -Confirm:$false -ErrorAction SilentlyContinue

            # Enable DHCP for IP address
            Set-NetIPInterface -InterfaceAlias $adapter.Name -Dhcp Enabled -ErrorAction Stop
            Write-Logger "DHCP enabled for IP address" "INFO"

            # Set DNS to automatic (DHCP) - always use automatic DNS with DHCP
            Set-DnsClientServerAddress -InterfaceAlias $adapter.Name -ResetServerAddresses -ErrorAction Stop
            Write-Logger "DNS set to automatic (DHCP)" "INFO"

            # Renew DHCP lease to get new configuration
            $null = Invoke-Command -ScriptBlock { ipconfig /renew } -ErrorAction SilentlyContinue
            Write-Logger "DHCP lease renewed" "INFO"
        }
        else {
            # Configure Static IP
            Write-Logger "Configuring static IP" "INFO"

            # Remove existing IP configuration
            Remove-NetIPAddress -InterfaceAlias $adapter.Name -Confirm:$false -ErrorAction SilentlyContinue
            Remove-NetRoute -InterfaceAlias $adapter.Name -Confirm:$false -ErrorAction SilentlyContinue

            # Disable DHCP
            Set-NetIPInterface -InterfaceAlias $adapter.Name -Dhcp Disabled -ErrorAction Stop

            # Convert subnet mask to prefix length if provided
            $prefixLength = 24  # Default /24
            if (-not [string]::IsNullOrEmpty($subnetMask)) {
                $prefixLength = Convert-SubnetMaskToPrefixLength $subnetMask
            }

            # Set IP address
            New-NetIPAddress -InterfaceAlias $adapter.Name -IPAddress $ipAddress -PrefixLength $prefixLength -ErrorAction Stop
            Write-Logger "Set static IP address: $ipAddress/$prefixLength" "INFO"

            # Set gateway if provided
            if (-not [string]::IsNullOrEmpty($gateway)) {
                New-NetRoute -InterfaceAlias $adapter.Name -DestinationPrefix "0.0.0.0/0" -NextHop $gateway -ErrorAction Stop
                Write-Logger "Set gateway: $gateway" "INFO"
            }

            # Set DNS servers if provided
            $dnsServers = @()
            if (-not [string]::IsNullOrEmpty($dnsServer)) {
                $dnsServers += $dnsServer
            }
            if (-not [string]::IsNullOrEmpty($dnsAltServer)) {
                $dnsServers += $dnsAltServer
            }

            if ($dnsServers.Count -gt 0) {
                Set-DnsClientServerAddress -InterfaceAlias $adapter.Name -ServerAddresses $dnsServers -ErrorAction Stop
                Write-Logger "Set DNS servers: $($dnsServers -join ', ')" "INFO"
            }
        }

        # Handle IPv6 settings (applies to both DHCP and Static)
        if ($disableIPv6) {
            # Disable IPv6 on the adapter
            Disable-NetAdapterBinding -Name $adapter.Name -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue
            Write-Logger "IPv6 disabled on adapter: $($adapter.Name)" "INFO"

            # Also disable IPv6 globally via registry (requires reboot to take full effect)
            try {
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters" -Name "DisabledComponents" -Value 0xff -Type DWord -ErrorAction Stop
                Write-Logger "IPv6 disabled globally (registry)" "INFO"
            }
            catch {
                Write-Logger "Warning: Could not disable IPv6 globally via registry: $($_.Exception.Message)" "WARNING"
            }
        }
        else {
            # Enable IPv6 on the adapter if it was disabled
            Enable-NetAdapterBinding -Name $adapter.Name -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue
            Write-Logger "IPv6 enabled on adapter: $($adapter.Name)" "INFO"

            # Enable IPv6 globally via registry
            try {
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters" -Name "DisabledComponents" -Value 0x00 -Type DWord -ErrorAction Stop
                Write-Logger "IPv6 enabled globally (registry)" "INFO"
            }
            catch {
                Write-Logger "Warning: Could not enable IPv6 globally via registry: $($_.Exception.Message)" "WARNING"
            }
        }

        Write-Logger "Network configuration completed successfully" "INFO"

        # Show completion message
        $configType = if ($useDHCP) { "DHCP" } else { "Static IP" }
        $ipv6Status = if ($disableIPv6) { "IPv6 wurde deaktiviert." } else { "IPv6 ist aktiviert." }
        $message = "Network configuration completed successfully.`n`nConfiguration: $configType`n$ipv6Status"

        if ($disableIPv6) {
            $message += "`n`nHinweis: Ein Neustart wird empfohlen für vollständige IPv6-Deaktivierung."
        }

        if ($useDHCP) {
            $message += "`n`nDHCP lease wurde erneuert. Neue IP-Konfiguration wird automatisch bezogen."
        }

        [System.Windows.MessageBox]::Show($message, "WDCA - Network Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
    }
    catch {
        Write-Logger "Error configuring network: $($_.Exception.Message)" "ERROR"
        [System.Windows.MessageBox]::Show("Error configuring network: $($_.Exception.Message)", "WDCA - Network Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
    }
}

function Invoke-RDPConfiguration {
    <#
    .SYNOPSIS
        Enables and configures Remote Desktop
    .DESCRIPTION
        Enables Remote Desktop and configures authentication settings without restart
    #>
    Write-Logger "Configuring Remote Desktop" "INFO"
    try {
        # Check current RDP status
        $currentRDPStatus = Get-ItemProperty -Path "HKLM:\System\CurrentControlSet\Control\Terminal Server" -Name "fDenyTSConnections" -ErrorAction SilentlyContinue
        $rdpWasDisabled = $currentRDPStatus.fDenyTSConnections -eq 1

        # Enable Remote Desktop
        Set-ItemProperty -Path "HKLM:\System\CurrentControlSet\Control\Terminal Server" -Name "fDenyTSConnections" -Value 0
        Write-Logger "Enabled Remote Desktop" "INFO"

        # Enable Remote Desktop through Windows Firewall
        try {
            Enable-NetFirewallRule -DisplayGroup "Remote Desktop" -ErrorAction Stop
            Write-Logger "Enabled Remote Desktop firewall rules" "INFO"
        }
        catch {
            # Fallback for older systems or different language versions
            netsh advfirewall firewall set rule group="Remote Desktop" new enable=yes
            Write-Logger "Enabled Remote Desktop firewall rules (netsh)" "INFO"
        }

        # Check if Network Level Authentication should be required
        $requireNLA = if ($sync.WPFRDPNetworkAuth) { $sync.WPFRDPNetworkAuth.IsChecked } else { $true }

        if ($requireNLA) {
            Set-ItemProperty -Path "HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name "UserAuthentication" -Value 1
            Write-Logger "Enabled Network Level Authentication for RDP" "INFO"
        }
        else {
            Set-ItemProperty -Path "HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name "UserAuthentication" -Value 0
            Write-Logger "Disabled Network Level Authentication for RDP" "INFO"
        }

        # Force refresh of Terminal Services configuration (no restart needed)
        try {
            # Restart Terminal Services to apply changes immediately
            $terminalService = Get-Service -Name "TermService" -ErrorAction SilentlyContinue
            if ($terminalService -and $terminalService.Status -eq "Running") {
                Write-Logger "Refreshing Terminal Services configuration" "INFO"
                Restart-Service -Name "TermService" -Force -ErrorAction Stop
                Write-Logger "Terminal Services restarted successfully" "INFO"
            }
            else {
                # Start the service if it's not running
                Start-Service -Name "TermService" -ErrorAction Stop
                Write-Logger "Terminal Services started" "INFO"
            }
        }
        catch {
            Write-Logger "Warning: Could not restart Terminal Services: $($_.Exception.Message)" "WARNING"
            Write-Logger "RDP settings applied, but may require manual service restart" "WARNING"
        }

        # Get current RDP port for information
        try {
            $rdpPort = Get-ItemProperty -Path "HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name "PortNumber" -ErrorAction SilentlyContinue
            if ($rdpPort) {
                Write-Logger "RDP is configured on port: $($rdpPort.PortNumber)" "INFO"
            }
        }
        catch {
            Write-Logger "Could not determine RDP port" "WARNING"
        }

        Write-Logger "Remote Desktop configuration completed successfully" "INFO"

        # Prepare status message
        $statusMessage = "Remote Desktop has been enabled and configured successfully.`n`n"
        $statusMessage += "Configuration applied:`n"
        $statusMessage += "- Remote Desktop: Enabled`n"
        $statusMessage += "- Firewall Rules: Enabled`n"
        $statusMessage += "- Network Level Auth: $(if ($requireNLA) { 'Enabled' } else { 'Disabled' })`n"
        $statusMessage += "- Terminal Services: Refreshed`n`n"
        $statusMessage += "RDP is ready to use immediately - no restart required."

        [System.Windows.MessageBox]::Show($statusMessage, "WDCA - RDP Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
    }
    catch {
        Write-Logger "Error configuring Remote Desktop: $($_.Exception.Message)" "ERROR"
        [System.Windows.MessageBox]::Show("Error configuring Remote Desktop: $($_.Exception.Message)", "WDCA - RDP Configuration", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
    }
}



function Clear-WDCARecycleBin {
    <#
    .SYNOPSIS
        Empties the recycle bin using multiple fallback methods
    #>
    try {
        Write-Logger "Clearing recycle bin" "INFO"

        # Method 1: COM Shell (primary)
        try {
            $shell = New-Object -ComObject Shell.Application
            $recycleBin = $shell.Namespace(0xA)
            if ($recycleBin -and $recycleBin.Items().Count -gt 0) {
                $recycleBin.InvokeVerb("Empty")
                Start-Sleep -Seconds 2
                Write-Logger "Recycle bin cleared via COM" "SUCCESS"
                return "Recycle bin emptied successfully"
            }
            else {
                return "Recycle bin was already empty"
            }
        }
        catch {
            Write-Logger "COM method failed: $($_.Exception.Message)" "WARNING"
        }
        finally {
            if ($shell) { [System.Runtime.Interopservices.Marshal]::ReleaseComObject($shell) | Out-Null }
        }

        # Method 2: rundll32 fallback
        try {
            $process = Start-Process -FilePath "rundll32.exe" -ArgumentList "shell32.dll,SHEmptyRecycleBinW" -Wait -PassThru -NoNewWindow
            if ($process.ExitCode -eq 0) {
                Write-Logger "Recycle bin cleared via rundll32" "SUCCESS"
                return "Recycle bin emptied successfully"
            }
        }
        catch {
            Write-Logger "rundll32 method failed: $($_.Exception.Message)" "WARNING"
        }

        return "Could not empty recycle bin - manual intervention may be required"
    }
    catch {
        Write-Logger "Error clearing recycle bin: $($_.Exception.Message)" "ERROR"
        return "Error emptying recycle bin"
    }
}

function Clear-TemporaryFiles {
    <#
    .SYNOPSIS
        Clears temporary files from standard locations
    #>
    $totalCleaned = 0
    $locations = @(
        @{Path = $env:TEMP; Name = "User Temp" },
        @{Path = "$env:SystemRoot\Temp"; Name = "System Temp" },
        @{Path = "$env:LocalAppData\Temp"; Name = "Local AppData Temp" }
    )

    foreach ($location in $locations) {
        if (-not (Test-Path $location.Path)) { continue }

        try {
            $files = Get-ChildItem -Path $location.Path -Recurse -File -ErrorAction SilentlyContinue
            $sizeBefore = ($files | Measure-Object -Property Length -Sum).Sum

            $removed = 0
            foreach ($file in $files) {
                try {
                    Remove-Item -Path $file.FullName -Force -ErrorAction Stop
                    $removed++
                }
                catch { }
            }

            $remainingFiles = Get-ChildItem -Path $location.Path -Recurse -File -ErrorAction SilentlyContinue
            $sizeAfter = ($remainingFiles | Measure-Object -Property Length -Sum).Sum
            $cleaned = $sizeBefore - $sizeAfter
            $totalCleaned += $cleaned

            Write-Logger "Cleaned $($location.Name) - $removed files, $([math]::Round($cleaned / 1MB, 2)) MB" "INFO"
        }
        catch {
            Write-Logger "Error cleaning $($location.Name): $($_.Exception.Message)" "ERROR"
        }
    }

    return "$([math]::Round($totalCleaned / 1MB, 2)) MB cleaned"
}

function Clear-EventLogs {
    <#
    .SYNOPSIS
        Clears Windows Event Logs
    #>
    try {
        $logs = Get-WinEvent -ListLog * -ErrorAction SilentlyContinue | Where-Object { $_.RecordCount -gt 0 }
        $clearedCount = 0

        foreach ($log in $logs) {
            try {
                [System.Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog($log.LogName)
                $clearedCount++
            }
            catch { }
        }

        Write-Logger "Cleared $clearedCount event logs" "INFO"
        return "$clearedCount logs cleared"
    }
    catch {
        Write-Logger "Error clearing event logs: $($_.Exception.Message)" "WARNING"
        return "Error clearing logs"
    }
}

# System Setup wrappers
function Invoke-WPFSystemSetup {
    param([ValidateSet("Network", "RDP")][string]$Action)

    switch ($Action) {
        "Network" { Invoke-NetworkConfiguration }
        "RDP" { Invoke-RDPConfiguration }
    }
}

function Invoke-SystemDiagnosticsAsync {
    Write-Logger "Starting comprehensive system diagnostics" "INFO"

    $confirmResult = [System.Windows.MessageBox]::Show(
        "Run comprehensive system diagnostics? This will run DISM, SFC, and CHKDSK sequentially.",
        "WDCA - System Diagnostics",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question
    )

    if ($confirmResult -eq [System.Windows.MessageBoxResult]::Yes) {
        Invoke-SystemTool -Tool "DISM"
        Start-Sleep -Seconds 2
        Invoke-SystemTool -Tool "SFC"
        Start-Sleep -Seconds 2
        Invoke-SystemTool -Tool "CHKDSK"
    }
}

function Invoke-PreCloneCleanup {
    Write-Logger "Starting pre-clone cleanup" "INFO"

    $cleanTemp = if ($sync.WPFCleanupTemp) { $sync.WPFCleanupTemp.IsChecked } else { $true }
    $cleanLogs = if ($sync.WPFCleanupLogs) { $sync.WPFCleanupLogs.IsChecked } else { $true }
    $cleanRecycle = if ($sync.WPFCleanupRecycle) { $sync.WPFCleanupRecycle.IsChecked } else { $true }

    $results = @()
    if ($cleanTemp) { $results += "Temp Files: $(Clear-TemporaryFiles)" }
    if ($cleanLogs) { $results += "Event Logs: $(Clear-EventLogs)" }
    if ($cleanRecycle) { $results += "Recycle Bin: $(Clear-WDCARecycleBin)" }

    [System.Windows.MessageBox]::Show(
        "Cleanup completed!`n`n" + ($results -join "`n"),
        "WDCA - Cleanup Complete",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Information
    )
}

function Invoke-WPFApplicationsAsync {
    <#
    .SYNOPSIS
        Application installation running in background with UI updates
    #>
    param(
        [ValidateSet("Background", "Silent")]
        [string]$Mode = "Background"
    )

    Write-Logger "Starting background application installation" "INFO"

    # Collect selected applications
    $selectedApps = @()
    if ($global:sync.configs.applications) {
        foreach ($app in $global:sync.configs.applications.PSObject.Properties) {
            $checkboxName = $app.Name
            if ($global:sync[$checkboxName] -and $global:sync[$checkboxName].IsChecked -eq $true) {
                $selectedApps += @{
                    Name        = $checkboxName
                    DisplayName = $app.Value.content
                    WingetId    = $app.Value.winget
                }
            }
        }
    }

    if ($selectedApps.Count -eq 0) {
        [System.Windows.MessageBox]::Show(
            "Please select at least one application to install.",
            "WDCA - No Selection",
            [System.Windows.MessageBoxButton]::OK,
            [System.Windows.MessageBoxImage]::Information
        )
        return
    }

    # Confirmation
    $appList = ($selectedApps | ForEach-Object { "• $($_.DisplayName)" }) -join "`n"
    $confirmResult = [System.Windows.MessageBox]::Show(
        "Install $($selectedApps.Count) selected applications in background?`n`n$appList`n`nInstallation will run silently while UI remains responsive.",
        "WDCA - Confirm Installation",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question
    )

    if ($confirmResult -ne [System.Windows.MessageBoxResult]::Yes) {
        Write-Logger "Application installation cancelled by user" "INFO"
        return
    }

    # Test WinGet availability
    try {
        $null = & winget --version 2>&1
        if ($LASTEXITCODE -ne 0) { throw "WinGet exit code: $LASTEXITCODE" }
    }
    catch {
        [System.Windows.MessageBox]::Show(
            "WinGet is not available. Please ensure WinGet is installed.",
            "WDCA - WinGet Error",
            [System.Windows.MessageBoxButton]::OK,
            [System.Windows.MessageBoxImage]::Error
        )
        return
    }

    # Start background installation
    Start-BackgroundInstallation -Apps $selectedApps
}

function Start-BackgroundInstallation {
    param([array]$Apps)

    Write-Logger "Starting silent background installation of $($Apps.Count) applications" "INFO"

    # UI vorbereiten
    $global:sync.Form.Dispatcher.Invoke([action] {
            if ($global:sync.WPFInstallSelectedApps) {
                $global:sync.WPFInstallSelectedApps.Content = "Installing... (0/$($Apps.Count))"
                $global:sync.WPFInstallSelectedApps.IsEnabled = $false
            }
            if ($global:sync.WPFProgressBar) {
                $global:sync.WPFProgressBar.Visibility = "Visible"
                $global:sync.WPFProgressBar.IsIndeterminate = $false
                $global:sync.WPFProgressBar.Value = 0
            }
        })

    Set-WDCAStatus "Installing applications... (0/$($Apps.Count))"

    # Hintergrundjob mit verbesserter Fehlerbehandlung
    $job = Start-Job -ScriptBlock {
        param($appList)

        try {
            $results = @{
                Type       = "FinalResult"
                TotalApps  = $appList.Count
                Successful = 0
                Failed     = 0
                Details    = @()
                StartTime  = Get-Date
            }

            Write-Output "JOB_STARTED"

            for ($i = 0; $i -lt $appList.Count; $i++) {
                $app = $appList[$i]
                $index = $i + 1

                Write-Output "Starting app $index of $($appList.Count): $($app.DisplayName)"

                try {
                    Write-Output "Installing: $($app.DisplayName)"

                    $psi = New-Object System.Diagnostics.ProcessStartInfo
                    $psi.FileName = "winget.exe"
                    $psi.Arguments = "install --id `"$($app.WingetId)`" --silent --accept-source-agreements --accept-package-agreements --force"
                    $psi.UseShellExecute = $false
                    $psi.RedirectStandardOutput = $true
                    $psi.RedirectStandardError = $true
                    $psi.CreateNoWindow = $true
                    $psi.WorkingDirectory = $env:TEMP

                    Write-Output "Starting process with args: $($psi.Arguments)"

                    $process = [System.Diagnostics.Process]::Start($psi)
                    $timeoutMs = 300000  # 5 Minuten Timeout

                    if ($process.WaitForExit($timeoutMs)) {
                        $stdout = $process.StandardOutput.ReadToEnd()
                        $stderr = $process.StandardError.ReadToEnd()
                        $exitCode = $process.ExitCode

                        Write-Output "Process completed with exit code: $exitCode"
                        if ($stdout) { Write-Output "STDOUT: $stdout" }
                        if ($stderr) { Write-Output "STDERR: $stderr" }

                        $isSuccess = $false
                        if ($exitCode -eq 0) {
                            $isSuccess = $true
                        }
                        elseif ($exitCode -eq -1978335189) {
                            $isSuccess = $true
                            Write-Output "App already installed"
                        }
                        elseif ($exitCode -eq -1978335212) {
                            $isSuccess = $true
                            Write-Output "No newer version available"
                        }
                        elseif ($stdout -like "*successfully installed*" -or $stdout -like "*Installation completed successfully*") {
                            $isSuccess = $true
                            Write-Output "Success detected via output analysis"
                        }

                        if ($isSuccess) {
                            $results.Successful++
                            $results.Details += "✓ $($app.DisplayName) - Success"
                            Write-Output "SUCCESS: $($app.DisplayName)"
                        }
                        else {
                            $results.Failed++
                            $errorMsg = if ($stderr) { $stderr.Trim() } else { "Exit code: $exitCode" }
                            $results.Details += "✗ $($app.DisplayName) - $errorMsg"
                            Write-Output "FAILED: $($app.DisplayName) - $errorMsg"
                        }
                    }
                    else {
                        try {
                            $process.Kill()
                        }
                        catch {

                        }
                        $results.Failed++
                        $results.Details += "✗ $($app.DisplayName) - Installation timeout"
                        Write-Output "TIMEOUT: $($app.DisplayName)"
                    }
                }
                catch {
                    $results.Failed++
                    $errorMsg = $_.Exception.Message
                    $results.Details += "✗ $($app.DisplayName) - Error: $errorMsg"
                    Write-Output "EXCEPTION: $($app.DisplayName) - $errorMsg"
                }
            }

            $results.EndTime = Get-Date
            $results.Duration = ($results.EndTime - $results.StartTime).ToString("mm':'ss")

            $finalJson = $results | ConvertTo-Json -Depth 3 -Compress
            Write-Output "FINAL_RESULT:$finalJson"
            Write-Output "JOB_COMPLETED"

            return "JOB_SUCCESS"
        }
        catch {
            Write-Output "CRITICAL_ERROR: $($_.Exception.Message)"
            Write-Error $_.Exception.Message
            throw
        }
    } -ArgumentList @($Apps)

    # Timer für Fortschritt mit verbesserter Nachrichtenverarbeitung
    $progressTimer = New-Object System.Windows.Threading.DispatcherTimer
    $progressTimer.Interval = [TimeSpan]::FromMilliseconds(500)
    $processedMessages = @()

    $progressTimer.Add_Tick({
            try {
                $jobState = $job.State
                Write-Logger "Job State: $jobState" "DEBUG"

                if ($jobState -eq "Running") {
                    $outputs = Receive-Job -Job $job -Keep

                    foreach ($output in $outputs) {
                        if ($output -notin $processedMessages) {
                            $processedMessages += $output
                            # Reduced DEBUG logging - nur bei wichtigen Events
                            if ($output -like "PROGRESS:*" -or $output -like "SUCCESS:*" -or $output -like "FAILED:*") {
                                Write-Logger "Job Output: $output" "DEBUG"
                            }

                            # Progress-Nachrichten verarbeiten
                            if ($output -like "PROGRESS:*") {
                                try {
                                    $progressData = $output.Replace("PROGRESS:", "") | ConvertFrom-Json

                                    $global:sync.Form.Dispatcher.Invoke([action] {
                                            if ($global:sync.WPFInstallSelectedApps) {
                                                $global:sync.WPFInstallSelectedApps.Content = "Installing... ($($progressData.Index)/$($progressData.Total))"
                                            }
                                            if ($global:sync.WPFProgressBar) {
                                                $global:sync.WPFProgressBar.Value = $progressData.PercentComplete
                                            }
                                        })

                                    Set-WDCAStatus "Installing $($progressData.CurrentApp) ($($progressData.Index)/$($progressData.Total))"
                                    Write-Logger "Progress: $($progressData.CurrentApp) ($($progressData.Index)/$($progressData.Total))" "INFO"
                                }
                                catch {
                                    Write-Logger "Error parsing progress: $($_.Exception.Message)" "WARNING"
                                }
                            }
                        }
                    }
                }
                elseif ($jobState -eq "Completed") {
                    $progressTimer.Stop()
                    Write-Logger "Job completed successfully" "INFO"

                    try {
                        $allOutputs = Receive-Job -Job $job -ErrorAction SilentlyContinue
                        Write-Logger "Retrieved $($allOutputs.Count) outputs from completed job" "DEBUG"

                        # Final Result aus JSON extrahieren
                        $finalResult = $null
                        $jobCompletedFound = $false

                        foreach ($output in $allOutputs) {
                            if ($output -eq "JOB_COMPLETED" -or $output -eq "JOB_SUCCESS") {
                                $jobCompletedFound = $true
                            }
                            if ($output -like "FINAL_RESULT:*") {
                                try {
                                    $finalResult = $output.Replace("FINAL_RESULT:", "") | ConvertFrom-Json
                                    Write-Logger "Final result parsed successfully" "DEBUG"
                                }
                                catch {
                                    Write-Logger "Error parsing final result: $($_.Exception.Message)" "ERROR"
                                }
                            }
                        }

                        if ($finalResult) {
                            Write-Logger "Installation completed: $($finalResult.Successful) successful, $($finalResult.Failed) failed in $($finalResult.Duration)" "SUCCESS"

                            # Success message erstellen
                            $summaryMessage = "Application installation completed in $($finalResult.Duration)`n`n"
                            $summaryMessage += "Successfully installed: $($finalResult.Successful)`n"
                            $summaryMessage += "Failed: $($finalResult.Failed)`n"
                            $summaryMessage += "Total processed: $($finalResult.TotalApps)"

                            if ($finalResult.Details -and $finalResult.Details.Count -gt 0) {
                                $summaryMessage += "`n`nDetails:`n" + ($finalResult.Details -join "`n")
                            }

                            # Icon und Titel basierend auf Ergebnis
                            if ($finalResult.Successful -eq $finalResult.TotalApps) {
                                $icon = [System.Windows.MessageBoxImage]::Information
                                $title = "WDCA - Installation Complete"
                            }
                            elseif ($finalResult.Successful -gt 0) {
                                $icon = [System.Windows.MessageBoxImage]::Warning
                                $title = "WDCA - Partial Success"
                            }
                            else {
                                $icon = [System.Windows.MessageBoxImage]::Error
                                $title = "WDCA - Installation Failed"
                            }

                            [System.Windows.MessageBox]::Show($summaryMessage, $title, [System.Windows.MessageBoxButton]::OK, $icon)
                        }
                        elseif ($jobCompletedFound) {
                            Write-Logger "Job completed but no final result - using fallback analysis" "WARNING"

                            # Fallback - zähle SUCCESS/FAILED Nachrichten
                            $successCount = ($allOutputs | Where-Object { $_ -like "SUCCESS:*" }).Count
                            $failedCount = ($allOutputs | Where-Object { $_ -like "FAILED:*" -or $_ -like "EXCEPTION:*" -or $_ -like "TIMEOUT:*" }).Count
                            $totalProcessed = $successCount + $failedCount

                            if ($totalProcessed -gt 0) {
                                $fallbackMessage = "Installation completed:`n`nSuccessfully installed: $successCount`nFailed: $failedCount`nTotal processed: $totalProcessed"

                                $fallbackIcon = if ($successCount -eq $totalProcessed) {
                                    [System.Windows.MessageBoxImage]::Information
                                }
                                elseif ($successCount -gt 0) {
                                    [System.Windows.MessageBoxImage]::Warning
                                }
                                else {
                                    [System.Windows.MessageBoxImage]::Error
                                }

                                [System.Windows.MessageBox]::Show($fallbackMessage, "WDCA - Installation Complete", [System.Windows.MessageBoxButton]::OK, $fallbackIcon)
                                Write-Logger "Fallback analysis: $successCount successful, $failedCount failed" "INFO"
                            }
                            else {
                                [System.Windows.MessageBox]::Show(
                                    "Installation process completed. Please verify if the application was installed successfully.",
                                    "WDCA - Installation Complete",
                                    [System.Windows.MessageBoxButton]::OK,
                                    [System.Windows.MessageBoxImage]::Information
                                )
                            }
                        }
                        else {
                            Write-Logger "Job completed but no completion markers found" "ERROR"
                            [System.Windows.MessageBox]::Show(
                                "Installation process may have completed but status is unclear. Please check if the application was installed.",
                                "WDCA - Installation Status Unknown",
                                [System.Windows.MessageBoxButton]::OK,
                                [System.Windows.MessageBoxImage]::Warning
                            )
                        }
                    }
                    catch {
                        Write-Logger "Error processing completed job: $($_.Exception.Message)" "ERROR"
                        [System.Windows.MessageBox]::Show(
                            "Installation completed but there was an error processing the results. Check if the application was installed successfully.",
                            "WDCA - Installation Error",
                            [System.Windows.MessageBoxButton]::OK,
                            [System.Windows.MessageBoxImage]::Warning
                        )
                    }

                    # UI zurücksetzen
                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFInstallSelectedApps) {
                                $global:sync.WPFInstallSelectedApps.Content = "Install Selected"
                                $global:sync.WPFInstallSelectedApps.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Value = 100
                                # Progress bar nach kurzer Zeit ausblenden
                                $hideTimer = New-Object System.Windows.Threading.DispatcherTimer
                                $hideTimer.Interval = [TimeSpan]::FromSeconds(1)
                                $hideTimer.Add_Tick({
                                        $global:sync.WPFProgressBar.Visibility = "Collapsed"
                                        $this.Stop()
                                    })
                                $hideTimer.Start()
                            }
                        })

                    Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
                    Set-WDCAStatus "Ready - Installation completed"
                }
                elseif ($jobState -eq "Failed") {
                    $progressTimer.Stop()
                    Write-Logger "Job marked as failed - analyzing outputs" "ERROR"

                    try {
                        $allOutputs = Receive-Job -Job $job -ErrorAction SilentlyContinue
                        $jobErrors = $job.ChildJobs[0].Error | ForEach-Object { $_.ToString() }

                        Write-Logger "Failed job outputs: $($allOutputs -join '; ')" "DEBUG"
                        Write-Logger "Failed job errors: $($jobErrors -join '; ')" "ERROR"

                        # Prüfen ob es ein CRITICAL_ERROR gab
                        $criticalErrors = $allOutputs | Where-Object { $_ -like "CRITICAL_ERROR:*" }

                        if ($criticalErrors.Count -gt 0) {
                            $errorMsg = ($criticalErrors | ForEach-Object { $_.Replace("CRITICAL_ERROR: ", "") }) -join "; "
                            [System.Windows.MessageBox]::Show(
                                "Installation failed with critical error:`n`n$errorMsg",
                                "WDCA - Installation Failed",
                                [System.Windows.MessageBoxButton]::OK,
                                [System.Windows.MessageBoxImage]::Error
                            )
                        }
                        else {
                            # Möglicherweise ist der Job nur wegen einem winget Exit-Code als failed markiert
                            # Schauen ob trotzdem SUCCESS-Nachrichten da sind
                            $successCount = ($allOutputs | Where-Object { $_ -like "SUCCESS:*" }).Count

                            if ($successCount -gt 0) {
                                Write-Logger "Job marked as failed but found $successCount successes - possible false positive" "WARNING"
                                [System.Windows.MessageBox]::Show(
                                    "Installation may have succeeded despite job failure status. Please check if the application was installed.",
                                    "WDCA - Installation Status Unclear",
                                    [System.Windows.MessageBoxButton]::OK,
                                    [System.Windows.MessageBoxImage]::Warning
                                )
                            }
                            else {
                                [System.Windows.MessageBox]::Show(
                                    "Installation job failed. Check logs for details.",
                                    "WDCA - Installation Failed",
                                    [System.Windows.MessageBoxButton]::OK,
                                    [System.Windows.MessageBoxImage]::Error
                                )
                            }
                        }
                    }
                    catch {
                        Write-Logger "Could not analyze failed job: $($_.Exception.Message)" "ERROR"
                        [System.Windows.MessageBox]::Show(
                            "Installation failed and error analysis also failed. Check logs for details.",
                            "WDCA - Installation Failed",
                            [System.Windows.MessageBoxButton]::OK,
                            [System.Windows.MessageBoxImage]::Error
                        )
                    }

                    # UI zurücksetzen
                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFInstallSelectedApps) {
                                $global:sync.WPFInstallSelectedApps.Content = "Install Selected"
                                $global:sync.WPFInstallSelectedApps.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Visibility = "Collapsed"
                            }
                        })

                    Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
                    Set-WDCAStatus "Ready - Installation failed"
                }
            }
            catch {
                $progressTimer.Stop()
                Write-Logger "Error in progress timer: $($_.Exception.Message)" "ERROR"

                # UI zurücksetzen bei Fehler
                try {
                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFInstallSelectedApps) {
                                $global:sync.WPFInstallSelectedApps.Content = "Install Selected"
                                $global:sync.WPFInstallSelectedApps.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Visibility = "Collapsed"
                            }
                        })
                }
                catch {
                    Write-Logger "Error resetting UI: $($_.Exception.Message)" "ERROR"
                }

                Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
                Set-WDCAStatus "Ready - Installation error"
            }
        }.GetNewClosure())

    $progressTimer.Start()
    Write-Logger "Background installation job started with progress monitoring" "INFO"
}

function Invoke-WPFListAppUpdates {
    <#
    .SYNOPSIS
        Lists available application updates in background with improved formatting
    #>
    Write-Logger "Checking for application updates in background" "INFO"

    # Update UI state
    if ($global:sync.WPFListAppUpdate) {
        $global:sync.WPFListAppUpdate.Content = "Checking..."
        $global:sync.WPFListAppUpdate.IsEnabled = $false
    }

    if ($global:sync.WPFProgressBar) {
        $global:sync.WPFProgressBar.Dispatcher.Invoke([action] {
                $global:sync.WPFProgressBar.Visibility = "Visible"
                $global:sync.WPFProgressBar.IsIndeterminate = $true
            })
    }

    Set-WDCAStatus "Scanning for application updates..."

    # Create background job for update checking
    $updateJob = Start-Job -ScriptBlock {
        try {
            # Execute winget upgrade command
            $processInfo = New-Object System.Diagnostics.ProcessStartInfo
            $processInfo.FileName = "winget.exe"
            $processInfo.Arguments = "upgrade --include-unknown"
            $processInfo.UseShellExecute = $false
            $processInfo.RedirectStandardOutput = $true
            $processInfo.RedirectStandardError = $true
            $processInfo.CreateNoWindow = $true

            $process = [System.Diagnostics.Process]::Start($processInfo)

            $output = $process.StandardOutput.ReadToEnd()
            $errorOutput = $process.StandardError.ReadToEnd()

            # Wait for process to complete with timeout
            $timeoutReached = -not $process.WaitForExit(60000) # 1 minute timeout

            if ($timeoutReached) {
                $process.Kill()
                throw "Update check timeout after 1 minute"
            }

            $results = @{
                Success  = $process.ExitCode -eq 0
                Output   = $output
                Error    = $errorOutput
                ExitCode = $process.ExitCode
            }

            # Improved parsing with fallback to original method
            if ($results.Success -and $results.Output) {
                $lines = $results.Output -split "`r?`n" | Where-Object { $_.Trim() -ne "" }

                # Method 1: Try improved parsing
                $headerFound = $false
                $updateEntries = @()

                foreach ($line in $lines) {
                    $trimmedLine = $line.Trim()

                    # Skip until we find the header line
                    if ($trimmedLine -match "Name\s+Id\s+Version\s+Available\s+Source") {
                        $headerFound = $true
                        continue
                    }

                    # Skip separator lines
                    if ($trimmedLine -match "^-+\s*$" -or $trimmedLine -eq "") {
                        continue
                    }

                    # Process update lines after header
                    if ($headerFound -and $trimmedLine -match "winget\s*$") {
                        try {
                            # Split line into components (winget output can be tricky with spacing)
                            $fields = $trimmedLine -split '\s{2,}' # Split on multiple spaces

                            if ($fields.Count -ge 4) {
                                $name = $fields[0].Trim()
                                $id = $fields[1].Trim()
                                $currentVersion = $fields[2].Trim()
                                $availableVersion = $fields[3].Trim().Replace(" winget", "")

                                # Create formatted entry
                                $formattedEntry = "$name`n  ID: $id`n  Current: $currentVersion → Available: $availableVersion"
                                $updateEntries += $formattedEntry
                            }
                            else {
                                # Fallback: try different parsing approach
                                $parts = $trimmedLine -split '\s+' | Where-Object { $_ -ne "" }
                                if ($parts.Count -ge 4) {
                                    $name = $parts[0]
                                    # ID is often the second-to-last or third-to-last item
                                    $availableVersion = $parts[-1].Replace("winget", "").Trim()
                                    $currentVersion = $parts[-2]
                                    $id = $parts[-3]

                                    if ($parts.Count -gt 4) {
                                        # Rebuild name from remaining parts
                                        $nameEnd = $parts.Length - 3
                                        $name = ($parts[0..($nameEnd - 1)] -join " ")
                                    }

                                    $formattedEntry = "$name`n  ID: $id`n  Current: $currentVersion → Available: $availableVersion"
                                    $updateEntries += $formattedEntry
                                }
                                else {
                                    # Add raw line as backup
                                    $updateEntries += $trimmedLine
                                }
                            }
                        }
                        catch {
                            # If parsing fails, use the raw line
                            $updateEntries += $trimmedLine
                        }
                    }
                }

                # Method 2: Fallback to original simple parsing if no updates found
                if ($updateEntries.Count -eq 0) {
                    Write-Output "DEBUG: Improved parsing found no updates, falling back to original method"

                    $simpleUpdateLines = $results.Output -split "`n" | Where-Object {
                        $_ -match "^[A-Za-z0-9].*[\d\.].*[\d\.].*winget" -and $_ -notmatch "Name.*Version"
                    }

                    if ($simpleUpdateLines.Count -gt 0) {
                        Write-Output "DEBUG: Original parsing found $($simpleUpdateLines.Count) updates"
                        # Use original lines but try to format them better
                        foreach ($line in $simpleUpdateLines) {
                            $parts = $line.Trim() -split '\s+' | Where-Object { $_ -ne "" }
                            if ($parts.Count -ge 3) {
                                $name = $parts[0]
                                $lastPart = $parts[-1]
                                if ($lastPart -eq "winget") {
                                    $available = $parts[-2]
                                    $current = if ($parts.Count -gt 3) { $parts[-3] } else { "Unknown" }
                                }
                                else {
                                    $available = $lastPart.Replace("winget", "").Trim()
                                    $current = $parts[-2]
                                }

                                $formattedEntry = "$name`n  Current: $current → Available: $available"
                                $updateEntries += $formattedEntry
                            }
                            else {
                                # Fallback to raw line
                                $updateEntries += $line.Trim()
                            }
                        }
                    }
                }

                $results.UpdateCount = $updateEntries.Count
                $results.Updates = $updateEntries

                # Debug output
                Write-Output "DEBUG: Final update count: $($results.UpdateCount)"
            }
            else {
                $results.UpdateCount = 0
                $results.Updates = @()
                Write-Output "DEBUG: No output or process failed"
            }

            return $results
        }
        catch {
            return @{
                Success     = $false
                Error       = $_.Exception.Message
                UpdateCount = 0
                Updates     = @()
            }
        }
    }

    # Monitor the update job with reduced timer frequency
    $updateTimer = New-Object System.Windows.Threading.DispatcherTimer
    $updateTimer.Interval = [TimeSpan]::FromSeconds(2)

    $updateTimer.Add_Tick({
            try {
                if ($updateJob.State -eq 'Completed') {
                    $this.Stop()

                    try {
                        $results = Receive-Job -Job $updateJob

                        # Update UI
                        $global:sync.Form.Dispatcher.Invoke([action] {
                                if ($global:sync.WPFListAppUpdate) {
                                    $global:sync.WPFListAppUpdate.Content = "List All Updates"
                                    $global:sync.WPFListAppUpdate.IsEnabled = $true
                                }
                                if ($global:sync.WPFProgressBar) {
                                    $global:sync.WPFProgressBar.Visibility = "Collapsed"
                                }
                            })

                        if ($results.Success) {
                            if ($results.UpdateCount -gt 0) {
                                # Join formatted entries with double newlines for better readability
                                $updateList = $results.Updates -join "`n`n"
                                $message = "Found $($results.UpdateCount) available updates:`n`n$updateList`n`n`nUse 'Update All Apps' to install all updates."
                                $icon = [System.Windows.MessageBoxImage]::Information
                                $title = "WDCA - Updates Available"

                                Write-Logger "Found $($results.UpdateCount) available updates" "INFO"
                            }
                            else {
                                $message = "All applications are up to date!"
                                $icon = [System.Windows.MessageBoxImage]::Information
                                $title = "WDCA - No Updates"

                                Write-Logger "No application updates available" "INFO"
                            }
                        }
                        else {
                            $message = "Error checking for updates: $($results.Error)"
                            $icon = [System.Windows.MessageBoxImage]::Error
                            $title = "WDCA - Update Check Failed"

                            Write-Logger "Update check failed: $($results.Error)" "ERROR"
                        }

                        [System.Windows.MessageBox]::Show($message, $title, [System.Windows.MessageBoxButton]::OK, $icon)
                        Set-WDCAStatus "Ready - Update check completed"
                    }
                    catch {
                        Write-Logger "Error processing update results: $($_.Exception.Message)" "ERROR"
                        Set-WDCAStatus "Ready - Update check completed with errors"
                    }
                    finally {
                        Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue
                    }
                }
                elseif ($updateJob.State -eq 'Failed') {
                    $this.Stop()

                    Write-Logger "Update check job failed" "ERROR"

                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFListAppUpdate) {
                                $global:sync.WPFListAppUpdate.Content = "List All Updates"
                                $global:sync.WPFListAppUpdate.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Visibility = "Collapsed"
                            }
                        })

                    [System.Windows.MessageBox]::Show(
                        "Update check failed. Please try again or check your internet connection.",
                        "WDCA - Update Check Error",
                        [System.Windows.MessageBoxButton]::OK,
                        [System.Windows.MessageBoxImage]::Error
                    )

                    Set-WDCAStatus "Ready - Update check failed"
                    Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue
                }
            }
            catch {
                Write-Logger "Error in update timer: $($_.Exception.Message)" "ERROR"
                $this.Stop()
                Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue
            }
        }.GetNewClosure())

    $updateTimer.Start()
    Write-Logger "Background update check started" "INFO"
}

function Invoke-WPFUpdateApps {
    <#
    .SYNOPSIS
        Updates all applications in background
    #>
    Write-Logger "Starting background application updates" "INFO"

    $confirmResult = [System.Windows.MessageBox]::Show(
        "Update all applications using WinGet in background?`n`nThis will update all installed applications silently while keeping the UI responsive.",
        "WDCA - Confirm Updates",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question
    )

    if ($confirmResult -ne [System.Windows.MessageBoxResult]::Yes) {
        Write-Logger "Updates cancelled by user" "INFO"
        return
    }

    # Update UI state
    if ($global:sync.WPFUpdateApps) {
        $global:sync.WPFUpdateApps.Content = "Updating..."
        $global:sync.WPFUpdateApps.IsEnabled = $false
    }

    if ($global:sync.WPFProgressBar) {
        $global:sync.WPFProgressBar.Dispatcher.Invoke([action] {
                $global:sync.WPFProgressBar.Visibility = "Visible"
                $global:sync.WPFProgressBar.IsIndeterminate = $true
            })
    }

    Set-WDCAStatus "Updating all applications..."

    # Create background job for updates
    $updateJob = Start-Job -ScriptBlock {
        try {
            $startTime = Get-Date

            # Execute winget upgrade command
            $processInfo = New-Object System.Diagnostics.ProcessStartInfo
            $processInfo.FileName = "winget.exe"
            $processInfo.Arguments = "upgrade --all --silent --accept-source-agreements --accept-package-agreements"
            $processInfo.UseShellExecute = $false
            $processInfo.RedirectStandardOutput = $true
            $processInfo.RedirectStandardError = $true
            $processInfo.CreateNoWindow = $true

            $process = [System.Diagnostics.Process]::Start($processInfo)

            $output = $process.StandardOutput.ReadToEnd()
            $errorOutput = $process.StandardError.ReadToEnd()

            # Wait for process to complete with timeout (15 minutes)
            $timeoutReached = -not $process.WaitForExit(900000)

            if ($timeoutReached) {
                $process.Kill()
                throw "Update process timeout after 15 minutes"
            }

            $endTime = Get-Date
            $duration = ($endTime - $startTime).ToString("mm':'ss")

            return @{
                Success   = $process.ExitCode -eq 0 -or $process.ExitCode -eq -1978335188
                Output    = $output
                Error     = $errorOutput
                ExitCode  = $process.ExitCode
                Duration  = $duration
                StartTime = $startTime
                EndTime   = $endTime
            }
        }
        catch {
            return @{
                Success  = $false
                Error    = $_.Exception.Message
                Duration = "00:00"
                ExitCode = -1
            }
        }
    }

    # Monitor the update job
    $updateTimer = New-Object System.Windows.Threading.DispatcherTimer
    $updateTimer.Interval = [TimeSpan]::FromSeconds(2)

    $updateTimer.Add_Tick({
            try {
                if ($updateJob.State -eq 'Completed') {
                    $this.Stop()

                    try {
                        $results = Receive-Job -Job $updateJob

                        # Update UI
                        $global:sync.Form.Dispatcher.Invoke([action] {
                                if ($global:sync.WPFUpdateApps) {
                                    $global:sync.WPFUpdateApps.Content = "Update All Apps"
                                    $global:sync.WPFUpdateApps.IsEnabled = $true
                                }
                                if ($global:sync.WPFProgressBar) {
                                    $global:sync.WPFProgressBar.Visibility = "Collapsed"
                                }
                            })

                        # Handle different exit codes properly
                        if ($results.Success) {
                            if ($results.ExitCode -eq -1978335188) {
                                $message = "All application updates completed successfully in $($results.Duration).`n`nNote: Some updates completed with warnings, which is normal for WinGet operations."
                                Write-Logger "Application updates completed with normal WinGet warnings in $($results.Duration)" "SUCCESS"
                            }
                            else {
                                $message = "All application updates completed successfully in $($results.Duration)."
                                Write-Logger "Application updates completed successfully in $($results.Duration)" "SUCCESS"
                            }
                            $icon = [System.Windows.MessageBoxImage]::Information
                            $title = "WDCA - Updates Complete"
                        }
                        else {
                            $message = "Application updates completed with issues in $($results.Duration).`n`nExit Code: $($results.ExitCode)"
                            if ($results.Error) {
                                $message += "`n`nError: $($results.Error)"
                            }
                            $icon = [System.Windows.MessageBoxImage]::Warning
                            $title = "WDCA - Updates Completed with Issues"

                            Write-Logger "Application updates completed with issues: Exit Code $($results.ExitCode)" "WARNING"
                        }

                        # Safe MessageBox call with fallback handling
                        try {
                            [System.Windows.MessageBox]::Show($message, $title, [System.Windows.MessageBoxButton]::OK, $icon)
                        }
                        catch {
                            Write-Logger "MessageBox display failed, trying fallback: $($_.Exception.Message)" "WARNING"
                            try {
                                # Fallback without icon
                                [System.Windows.MessageBox]::Show($message, $title, [System.Windows.MessageBoxButton]::OK)
                            }
                            catch {
                                Write-Logger "All MessageBox attempts failed: $($_.Exception.Message)" "ERROR"
                                # Log the message instead
                                Write-Logger "Update Result: $message" "INFO"
                            }
                        }

                        Set-WDCAStatus "Ready - Updates completed"
                    }
                    catch {
                        Write-Logger "Error processing update results: $($_.Exception.Message)" "ERROR"

                        # Safe UI reset
                        try {
                            $global:sync.Form.Dispatcher.Invoke([action] {
                                    if ($global:sync.WPFUpdateApps) {
                                        $global:sync.WPFUpdateApps.Content = "Update All Apps"
                                        $global:sync.WPFUpdateApps.IsEnabled = $true
                                    }
                                    if ($global:sync.WPFProgressBar) {
                                        $global:sync.WPFProgressBar.Visibility = "Collapsed"
                                    }
                                })
                        }
                        catch {
                            Write-Logger "Failed to reset UI after error: $($_.Exception.Message)" "ERROR"
                        }

                        Set-WDCAStatus "Ready - Updates completed with errors"
                    }
                    finally {
                        Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue
                    }
                }
                elseif ($updateJob.State -eq 'Failed') {
                    $this.Stop()

                    Write-Logger "Update job failed" "ERROR"

                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFUpdateApps) {
                                $global:sync.WPFUpdateApps.Content = "Update All Apps"
                                $global:sync.WPFUpdateApps.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Visibility = "Collapsed"
                            }
                        })

                    # Safe MessageBox for error case
                    try {
                        [System.Windows.MessageBox]::Show(
                            "Application updates failed. Please try again or check your internet connection.",
                            "WDCA - Update Error",
                            [System.Windows.MessageBoxButton]::OK,
                            [System.Windows.MessageBoxImage]::Error
                        )
                    }
                    catch {
                        Write-Logger "Failed to show error MessageBox: $($_.Exception.Message)" "ERROR"
                        Write-Logger "Update Error: Application updates failed. Please try again or check your internet connection." "ERROR"
                    }

                    Set-WDCAStatus "Ready - Updates failed"
                    Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue
                }
            }
            catch {
                Write-Logger "Error in update timer: $($_.Exception.Message)" "ERROR"
                $this.Stop()
                Remove-Job -Job $updateJob -Force -ErrorAction SilentlyContinue

                # Emergency UI reset
                try {
                    $global:sync.Form.Dispatcher.Invoke([action] {
                            if ($global:sync.WPFUpdateApps) {
                                $global:sync.WPFUpdateApps.Content = "Update All Apps"
                                $global:sync.WPFUpdateApps.IsEnabled = $true
                            }
                            if ($global:sync.WPFProgressBar) {
                                $global:sync.WPFProgressBar.Visibility = "Collapsed"
                            }
                        })
                }
                catch {
                    Write-Logger "Emergency UI reset failed: $($_.Exception.Message)" "ERROR"
                }

                Set-WDCAStatus "Ready - Update process error"
            }
        }.GetNewClosure())

    $updateTimer.Start()
    Write-Logger "Background update job started" "INFO"
}

