$inputXML = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Windows Deployment and Configuration Assistant"
        Height="900"
        Width="1400"
        MinHeight="700"
        MinWidth="1200"
        WindowStartupLocation="CenterScreen"
        TextOptions.TextFormattingMode="Display"
        TextOptions.TextRenderingMode="ClearType"
        UseLayoutRounding="True"
        SnapsToDevicePixels="True"
        Background="{DynamicResource LayerBackgroundBrush}">

        <Window.Resources>
                <!-- Fluent Accent Colors -->
                <SolidColorBrush x:Key="SystemAccentBrush" Color="#FF0078D4"/>
                <SolidColorBrush x:Key="SystemAccentLightBrush" Color="#FF3399FF"/>
                <SolidColorBrush x:Key="SystemAccentDarkBrush" Color="#FF005A9E"/>

                <!-- Background Layers -->
                <SolidColorBrush x:Key="CardBackgroundBrush" Color="#FF2D2D30"/>
                <SolidColorBrush x:Key="LayerBackgroundBrush" Color="#FF1E1E1E"/>
                <SolidColorBrush x:Key="SurfaceBackgroundBrush" Color="#FF252526"/>
                <SolidColorBrush x:Key="ConsoleBackgroundBrush" Color="#FF0C0C0C"/>

                <!-- Text Colors -->
                <SolidColorBrush x:Key="TextPrimaryBrush" Color="#FFFFFFFF"/>
                <SolidColorBrush x:Key="TextSecondaryBrush" Color="#FFE0E0E0"/>
                <SolidColorBrush x:Key="TextTertiaryBrush" Color="#FFB0B0B0"/>
                <SolidColorBrush x:Key="ConsoleTextBrush" Color="#FF00FF00"/>

                <!-- Border / Hover -->
                <SolidColorBrush x:Key="BorderBrush" Color="#FF3A3A3A"/>
                <SolidColorBrush x:Key="HoverBrush" Color="#FF3C3C3C"/>

                <!-- Console Style -->
                <Style x:Key="ConsoleTextBox" TargetType="TextBox">
                <Setter Property="Background" Value="{StaticResource ConsoleBackgroundBrush}"/>
                <Setter Property="Foreground" Value="{StaticResource ConsoleTextBrush}"/>
                <Setter Property="FontFamily" Value="Consolas, Courier New"/>
                <Setter Property="FontSize" Value="13"/>
                <Setter Property="BorderThickness" Value="1"/>
                <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
                <Setter Property="Padding" Value="8"/>
                <Setter Property="CaretBrush" Value="{StaticResource ConsoleTextBrush}"/>
                <Setter Property="SelectionBrush" Value="{StaticResource SystemAccentBrush}"/>
                <Setter Property="TextWrapping" Value="Wrap"/>
                </Style>

                <!-- Console Input -->
                <Style x:Key="ConsoleInput" TargetType="TextBox" BasedOn="{StaticResource ConsoleTextBox}">
                <Setter Property="Height" Value="34"/>
                <Setter Property="VerticalAlignment" Value="Center"/>
                <Setter Property="TextWrapping" Value="NoWrap"/>
                </Style>

                <!-- Card -->
                <Style x:Key="ModernCard" TargetType="Border">
                <Setter Property="Background" Value="{StaticResource CardBackgroundBrush}"/>
                <Setter Property="CornerRadius" Value="6"/>
                <Setter Property="BorderThickness" Value="1"/>
                <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
                <Setter Property="Margin" Value="0,0,0,12"/>
                <Setter Property="Padding" Value="16"/>
                <Setter Property="Effect">
                        <Setter.Value>
                        <DropShadowEffect Color="Black" BlurRadius="6" ShadowDepth="2" Opacity="0.25"/>
                        </Setter.Value>
                </Setter>
                </Style>

                <!-- Primary Button -->
                <Style x:Key="FluentButton" TargetType="Button">
                <Setter Property="Background" Value="{StaticResource SystemAccentBrush}"/>
                <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                <Setter Property="BorderThickness" Value="0"/>
                <Setter Property="Padding" Value="14,8"/>
                <Setter Property="Margin" Value="4,2"/>
                <Setter Property="FontSize" Value="13"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
                <Setter Property="Cursor" Value="Hand"/>
                <Setter Property="Height" Value="36"/>
                <Setter Property="MinWidth" Value="120"/>
                <Setter Property="SnapsToDevicePixels" Value="True"/>
                <Setter Property="Template">
                        <Setter.Value>
                        <ControlTemplate TargetType="Button">
                                <Border x:Name="border"
                                        Background="{TemplateBinding Background}"
                                        CornerRadius="6"
                                        BorderThickness="{TemplateBinding BorderThickness}"
                                        BorderBrush="{TemplateBinding BorderBrush}">
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="{StaticResource SystemAccentLightBrush}"/>
                                </Trigger>
                                <Trigger Property="IsPressed" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="{StaticResource SystemAccentDarkBrush}"/>
                                </Trigger>
                                <Trigger Property="IsEnabled" Value="False">
                                        <Setter TargetName="border" Property="Opacity" Value="0.5"/>
                                </Trigger>
                                </ControlTemplate.Triggers>
                        </ControlTemplate>
                        </Setter.Value>
                </Setter>
                </Style>

                <!-- Secondary -->
                <Style x:Key="FluentButtonSecondary" TargetType="Button" BasedOn="{StaticResource FluentButton}">
                <Setter Property="Background" Value="Transparent"/>
                <Setter Property="BorderThickness" Value="1"/>
                <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
                </Style>

                <!-- Success / Warning / Danger -->
                <Style x:Key="FluentButtonSuccess" TargetType="Button" BasedOn="{StaticResource FluentButton}">
                <Setter Property="Background" Value="#FF107C10"/>
                </Style>
                <Style x:Key="FluentButtonWarning" TargetType="Button" BasedOn="{StaticResource FluentButton}">
                <Setter Property="Background" Value="#FFFF8C00"/>
                </Style>
                <Style x:Key="FluentButtonDanger" TargetType="Button" BasedOn="{StaticResource FluentButton}">
                <Setter Property="Background" Value="#FFD13438"/>
                </Style>

                <!-- Navigation -->
                <Style x:Key="NavigationButton" TargetType="Button">
                <Setter Property="Background" Value="Transparent"/>
                <Setter Property="Foreground" Value="{StaticResource TextSecondaryBrush}"/>
                <Setter Property="BorderThickness" Value="0"/>
                <Setter Property="Padding" Value="18,14"/>
                <Setter Property="FontSize" Value="14"/>
                <Setter Property="FontWeight" Value="Medium"/>
                <Setter Property="HorizontalAlignment" Value="Stretch"/>
                <Setter Property="HorizontalContentAlignment" Value="Left"/>
                <Setter Property="Cursor" Value="Hand"/>
                <Setter Property="Template">
                        <Setter.Value>
                        <ControlTemplate TargetType="Button">
                                <Border x:Name="border"
                                        Background="{TemplateBinding Background}"
                                        CornerRadius="6"
                                        Margin="6,2">
                                <Grid>
                                        <Rectangle x:Name="indicator"
                                                Width="4"
                                                HorizontalAlignment="Left"
                                                Fill="{StaticResource SystemAccentBrush}"
                                                Opacity="0"
                                                RadiusX="2" RadiusY="2"/>
                                        <ContentPresenter Margin="16,0,0,0" VerticalAlignment="Center"/>
                                </Grid>
                                </Border>
                                <ControlTemplate.Triggers>
                                <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="{StaticResource HoverBrush}"/>
                                        <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                                </Trigger>
                                <Trigger Property="Tag" Value="Selected">
                                        <Setter TargetName="border" Property="Background" Value="{StaticResource HoverBrush}"/>
                                        <Setter TargetName="indicator" Property="Opacity" Value="1"/>
                                        <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                                </Trigger>
                                </ControlTemplate.Triggers>
                        </ControlTemplate>
                        </Setter.Value>
                </Setter>
                </Style>

                <!-- CheckBox -->
                <Style x:Key="FluentCheckBox" TargetType="CheckBox">
                <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                <Setter Property="FontSize" Value="13"/>
                <Setter Property="Margin" Value="0,4"/>
                <Setter Property="Template">
                        <Setter.Value>
                        <ControlTemplate TargetType="CheckBox">
                                <Grid>
                                <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="Auto"/>
                                        <ColumnDefinition Width="*"/>
                                </Grid.ColumnDefinitions>
                                <Border x:Name="checkBorder"
                                        Grid.Column="0"
                                        Width="18" Height="18"
                                        Background="{StaticResource CardBackgroundBrush}"
                                        BorderBrush="{StaticResource BorderBrush}"
                                        BorderThickness="1"
                                        CornerRadius="3"
                                        Margin="0,0,6,0">
                                        <Path x:Name="checkMark"
                                        Data="M 2 9 L 7 14 L 16 4"
                                        Stroke="{StaticResource TextPrimaryBrush}"
                                        StrokeThickness="2"
                                        Opacity="0"/>
                                </Border>
                                <ContentPresenter Grid.Column="1" VerticalAlignment="Center" Content="{TemplateBinding Content}"/>
                                </Grid>
                                <ControlTemplate.Triggers>
                                <Trigger Property="IsChecked" Value="True">
                                        <Setter TargetName="checkBorder" Property="Background" Value="{StaticResource SystemAccentBrush}"/>
                                        <Setter TargetName="checkBorder" Property="BorderBrush" Value="{StaticResource SystemAccentBrush}"/>
                                        <Setter TargetName="checkMark" Property="Opacity" Value="1"/>
                                        <Setter TargetName="checkMark" Property="Stroke" Value="White"/>
                                </Trigger>
                                <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="checkBorder" Property="BorderBrush" Value="{StaticResource SystemAccentLightBrush}"/>
                                </Trigger>
                                </ControlTemplate.Triggers>
                        </ControlTemplate>
                        </Setter.Value>
                </Setter>
                </Style>

                <!-- ProgressBar -->
                <Style x:Key="FluentProgressBar" TargetType="ProgressBar">
                <Setter Property="Background" Value="{StaticResource BorderBrush}"/>
                <Setter Property="Foreground" Value="{StaticResource SystemAccentBrush}"/>
                <Setter Property="Height" Value="4"/>
                <Setter Property="Template">
                        <Setter.Value>
                        <ControlTemplate TargetType="ProgressBar">
                                <Grid>
                                <Border Background="{TemplateBinding Background}" CornerRadius="2"/>
                                <Grid x:Name="PART_Indicator" HorizontalAlignment="Left" ClipToBounds="True">
                                        <Rectangle x:Name="Indicator" Fill="{TemplateBinding Foreground}" RadiusX="2" RadiusY="2"/>
                                </Grid>
                                </Grid>
                        </ControlTemplate>
                        </Setter.Value>
                </Setter>
                </Style>

                <!-- Text Styles -->
                <Style x:Key="HeaderText" TargetType="TextBlock">
                <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                <Setter Property="FontSize" Value="24"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
                <Setter Property="Margin" Value="0,0,0,10"/>
                </Style>
                <Style x:Key="SubtitleText" TargetType="TextBlock">
                <Setter Property="Foreground" Value="{StaticResource TextSecondaryBrush}"/>
                <Setter Property="FontSize" Value="14"/>
                <Setter Property="Margin" Value="0,0,0,18"/>
                </Style>
                <Style x:Key="SectionHeader" TargetType="TextBlock">
                <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                <Setter Property="FontSize" Value="14"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
                <Setter Property="Margin" Value="0,0,0,6"/>
                </Style>
                <Style x:Key="FluentLabel" TargetType="Label">
                <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                <Setter Property="FontSize" Value="14"/>
                <Setter Property="Margin" Value="0,0,0,4"/>
                </Style>
        </Window.Resources>

        <Grid>
                <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- App Header -->
                <Border Grid.Row="0" Background="{StaticResource SurfaceBackgroundBrush}" Padding="20,15">
                        <Grid>
                                <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="Auto"/>
                                        <ColumnDefinition Width="*"/>
                                        <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>

                                <!-- App Icon and Title -->
                                <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                                        <!-- Icon placeholder -->
                                        <Border Width="32" Height="32" Background="{StaticResource SystemAccentBrush}" CornerRadius="6" Margin="0,0,12,0">
                                                <TextBlock Text="W" FontSize="18" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                        </Border>
                                        <StackPanel>
                                                <TextBlock Text="Windows Deployment and Configuration Assistant" FontSize="16" FontWeight="SemiBold" Foreground="{StaticResource TextPrimaryBrush}"/>
                                                <TextBlock Text="Streamline your Windows deployments and configurations" FontSize="12" Foreground="{StaticResource TextSecondaryBrush}"/>
                                        </StackPanel>
                                </StackPanel>

                                <!-- Console Toggle -->
                                <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                                        <Button Name="WPFToggleConsole" Content="Show Console" Style="{StaticResource FluentButtonSecondary}"/>
                                        <Button Name="WPFClearConsole" Content="Clear" Style="{StaticResource FluentButtonSecondary}" Margin="8,0,0,0"/>
                                </StackPanel>
                        </Grid>
                </Border>

                <!-- Main Content Area -->
                <Grid Grid.Row="1">
                        <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="280"/>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Name="ConsoleColumn" Width="0"/>
                        </Grid.ColumnDefinitions>

                        <!-- Navigation Sidebar -->
                        <Border Grid.Column="0" Background="{StaticResource SurfaceBackgroundBrush}" BorderBrush="{StaticResource BorderBrush}" BorderThickness="0,0,1,0">
                                <StackPanel Margin="16,24">
                                        <TextBlock Text="Navigation" Style="{StaticResource SectionHeader}" Margin="8,0,0,16"/>

                                        <Button Name="NavDebloat" Content="Debloat" Style="{StaticResource NavigationButton}" Tag="Selected"/>
                                        <Button Name="NavApplications" Content="Applications" Style="{StaticResource NavigationButton}"/>
                                        <Button Name="NavSystemSetup" Content="System Setup" Style="{StaticResource NavigationButton}"/>
                                        <Button Name="NavTroubleshooting" Content="Troubleshooting" Style="{StaticResource NavigationButton}"/>
                                        <Button Name="NavCloning" Content="Cloning" Style="{StaticResource NavigationButton}"/>

                                        <Separator Margin="8,20" Background="{StaticResource BorderBrush}"/>

                                        <Button Name="NavAbout" Content="About" Style="{StaticResource NavigationButton}"/>
                                </StackPanel>
                        </Border>

                        <!-- Content Area -->
                        <Grid Grid.Column="1" Name="ContentArea" Background="{StaticResource LayerBackgroundBrush}">

                                <!-- Debloat Content -->
                                <Grid Name="DebloatContent" Visibility="Visible">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="20">
                                                <StackPanel>
                                                        <TextBlock Text="Application Debloat" Style="{StaticResource HeaderText}"/>
                                                        <TextBlock Text="Remove unwanted applications and bloatware from your system" Style="{StaticResource SubtitleText}"/>

                                                        <!-- Quick Actions -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Quick Actions" Style="{StaticResource SectionHeader}"/>
                                                                        <StackPanel Orientation="Horizontal" Margin="0,4,0,0">
                                                                                <Button Name="WPFRefreshDebloatList" Content="Refresh List" Style="{StaticResource FluentButtonSecondary}"/>
                                                                                <Button Name="WPFUninstallSelected" Content="Uninstall Selected" Style="{StaticResource FluentButtonDanger}"/>
                                                                        </StackPanel>
                                                                </StackPanel>
                                                        </Border>

                                                        <!-- Applications List -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Installed Applications" Style="{StaticResource SectionHeader}"/>
                                                                        <TextBlock Text="Select applications to remove from your system. Use caution when removing system applications." Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,12"/>
                                                                        <ScrollViewer Name="DebloatScrollViewer" Height="450" VerticalScrollBarVisibility="Auto">
                                                                                <StackPanel Name="WPFDebloatPanel"/>
                                                                        </ScrollViewer>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>

                                <!-- Applications Content -->
                                <Grid Name="ApplicationsContent" Visibility="Collapsed">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="20">
                                                <StackPanel>
                                                        <TextBlock Text="Application Management" Style="{StaticResource HeaderText}"/>
                                                        <TextBlock Text="Install and manage applications using WinGet package manager" Style="{StaticResource SubtitleText}"/>

                                                        <!-- Quick Actions -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Quick Actions" Style="{StaticResource SectionHeader}"/>
                                                                        <StackPanel Orientation="Horizontal" Margin="0,4,0,0">
                                                                                <Button Name="WPFSelectAllApps" Content="Select All" Style="{StaticResource FluentButtonSecondary}"/>
                                                                                <Button Name="WPFDeselectAllApps" Content="Deselect All" Style="{StaticResource FluentButtonSecondary}"/>
                                                                                <Button Name="WPFInstallSelectedApps" Content="Install Selected" Style="{StaticResource FluentButtonSuccess}"/>
                                                                                <Button Name="WPFListAppUpdate" Content="List All Updates" Style="{StaticResource FluentButton}"/>
                                                                                <Button Name="WPFUpdateApps" Content="Update All Apps" Style="{StaticResource FluentButton}"/>
                                                                        </StackPanel>
                                                                </StackPanel>
                                                        </Border>

                                                        <!-- Application Categories -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Available Applications" Style="{StaticResource SectionHeader}"/>
                                                                        <ScrollViewer Name="ApplicationsScrollViewer" Height="350" VerticalScrollBarVisibility="Auto">
                                                                                <StackPanel Name="WPFApplicationsPanel"/>
                                                                        </ScrollViewer>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>

                                <!-- System Setup Content -->
                                <Grid Name="SystemSetupContent" Visibility="Collapsed">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="20">
                                                <StackPanel>
                                                        <TextBlock Text="System Configuration" Style="{StaticResource HeaderText}"/>
                                                        <TextBlock Text="Configure network settings, remote access, and server roles" Style="{StaticResource SubtitleText}"/>

                                                        <!-- Network Configuration -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Network Configuration" Style="{StaticResource SectionHeader}"/>
                                                                        <Grid Margin="0,4,0,0">
                                                                                <Grid.ColumnDefinitions>
                                                                                        <ColumnDefinition Width="*"/>
                                                                                        <ColumnDefinition Width="*"/>
                                                                                </Grid.ColumnDefinitions>
                                                                                <Grid.RowDefinitions>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                </Grid.RowDefinitions>

                                                                                <!-- Network Configuration Mode -->
                                                                                <Label Grid.Row="0" Grid.ColumnSpan="2" Content="Network Configuration Mode" Style="{StaticResource FluentLabel}" Margin="0,0,0,4"/>
                                                                                <StackPanel Grid.Row="1" Grid.ColumnSpan="2" Orientation="Horizontal" Margin="0,0,0,16">
                                                                                        <RadioButton Name="WPFStaticIP" Content="Static IP" IsChecked="True" Margin="0,0,24,0" FontSize="14" Foreground="White"/>
                                                                                        <RadioButton Name="WPFDHCP" Content="DHCP" Margin="0,0,0,0" FontSize="14" Foreground="White"/>
                                                                                </StackPanel>

                                                                                <!-- IP Address -->
                                                                                <Label Grid.Row="2" Grid.Column="0" Content="IP Address" Style="{StaticResource FluentLabel}" Margin="0,0,8,4"/>
                                                                                <TextBox Grid.Row="3" Grid.Column="0" Name="WPFNetworkIP" Margin="0,0,8,12" FontSize="14" Foreground="#000000" Background="#FFFFFF" BorderBrush="#CCCCCC" BorderThickness="2" Padding="8,6" MinHeight="32" CaretBrush="Black" SelectionBrush="LightBlue"/>

                                                                                <!-- Subnet Mask -->
                                                                                <Label Grid.Row="2" Grid.Column="1" Content="Subnet Mask" Style="{StaticResource FluentLabel}" Margin="8,0,0,4"/>
                                                                                <TextBox Grid.Row="3" Grid.Column="1" Name="WPFNetworkSubnet" Margin="8,0,0,12" FontSize="14" Foreground="#000000" Background="#FFFFFF" BorderBrush="#CCCCCC" BorderThickness="2" Padding="8,6" MinHeight="32" CaretBrush="Black" SelectionBrush="LightBlue"/>

                                                                                <!-- Gateway -->
                                                                                <Label Grid.Row="4" Grid.Column="0" Content="Gateway" Style="{StaticResource FluentLabel}" Margin="0,0,8,4"/>
                                                                                <TextBox Grid.Row="5" Grid.Column="0" Name="WPFNetworkGateway" Margin="0,0,8,12" FontSize="14" Foreground="#000000" Background="#FFFFFF" BorderBrush="#CCCCCC" BorderThickness="2" Padding="8,6" MinHeight="32" CaretBrush="Black" SelectionBrush="LightBlue"/>

                                                                                <!-- DNS Server -->
                                                                                <Label Grid.Row="4" Grid.Column="1" Content="DNS Server" Style="{StaticResource FluentLabel}" Margin="8,0,0,4"/>
                                                                                <TextBox Grid.Row="5" Grid.Column="1" Name="WPFNetworkDNS" Margin="8,0,0,12" FontSize="14" Foreground="#000000" Background="#FFFFFF" BorderBrush="#CCCCCC" BorderThickness="2" Padding="8,6" MinHeight="32" CaretBrush="Black" SelectionBrush="LightBlue"/>

                                                                                <!-- Alternative DNS Server -->
                                                                                <Label Grid.Row="6" Grid.Column="0" Content="Alternative DNS" Style="{StaticResource FluentLabel}" Margin="0,0,8,4"/>
                                                                                <TextBox Grid.Row="7" Grid.Column="0" Name="WPFNetworkDNSAlt" Margin="0,0,8,12" FontSize="14" Foreground="#000000" Background="#FFFFFF" BorderBrush="#CCCCCC" BorderThickness="2" Padding="8,6" MinHeight="32" CaretBrush="Black" SelectionBrush="LightBlue"/>

                                                                                <!-- IPv6 Option -->
                                                                                <CheckBox Grid.Row="7" Grid.Column="1" Name="WPFDisableIPv6" Content="Disable IPv6" VerticalAlignment="Center" Margin="8,0,0,12" FontSize="14" Foreground="White"/>

                                                                                <!-- Apply Button -->
                                                                                <Button Grid.Row="8" Grid.ColumnSpan="2" Name="WPFConfigureNetwork" Content="Apply Network Configuration" Style="{StaticResource FluentButton}" HorizontalAlignment="Left" Margin="0,4,0,0"/>
                                                                        </Grid>
                                                                </StackPanel>
                                                        </Border>

                                                        <!-- Remote Access -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Remote Access" Style="{StaticResource SectionHeader}"/>
                                                                        <CheckBox Name="WPFRDPNetworkAuth" Content="Require Network Level Authentication" Style="{StaticResource FluentCheckBox}" IsChecked="True" Margin="0,4,0,8"/>
                                                                        <Button Name="WPFEnableRDP" Content="Enable Remote Desktop" Style="{StaticResource FluentButton}" HorizontalAlignment="Left"/>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>

                                <!-- Troubleshooting Content -->
                                <Grid Name="TroubleshootingContent" Visibility="Collapsed">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="24">
                                                <StackPanel>
                                                        <TextBlock Text="System Diagnostics" Style="{StaticResource HeaderText}"/>
                                                        <TextBlock Text="Run system diagnostics and troubleshooting tools" Style="{StaticResource SubtitleText}"/>

                                                        <!-- System Diagnostics -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="System Health Checks" Style="{StaticResource SectionHeader}"/>
                                                                        <WrapPanel>
                                                                                <Button Name="WPFRunDISM" Content="Run DISM Scan" Style="{StaticResource FluentButton}"/>
                                                                                <Button Name="WPFRunSFC" Content="Run SFC Scan" Style="{StaticResource FluentButton}"/>
                                                                                <Button Name="WPFRunCHKDSK" Content="Run CHKDSK" Style="{StaticResource FluentButton}"/>
                                                                                <Button Name="WPFRunDiagnostics" Content="Run All Diagnostics" Style="{StaticResource FluentButtonWarning}"/>
                                                                        </WrapPanel>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>

                                <!-- Cloning Content -->
                                <Grid Name="CloningContent" Visibility="Collapsed">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="24">
                                                <StackPanel>
                                                        <!-- Cleanup Options -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="Pre-Clone Cleanup" Style="{StaticResource SectionHeader}"/>
                                                                        <TextBlock Text="Clean temporary files and optimize system for imaging" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,16"/>

                                                                        <StackPanel Orientation="Horizontal" Margin="0,0,0,20">
                                                                                <CheckBox Name="WPFCleanupTemp" Content="Clear Temp Files" Style="{StaticResource FluentCheckBox}" IsChecked="True" Margin="0,0,24,0"/>
                                                                                <CheckBox Name="WPFCleanupLogs" Content="Clear Event Logs" Style="{StaticResource FluentCheckBox}" IsChecked="True" Margin="0,0,24,0"/>
                                                                                <CheckBox Name="WPFCleanupRecycle" Content="Empty Recycle Bin" Style="{StaticResource FluentCheckBox}" IsChecked="True"/>
                                                                        </StackPanel>

                                                                        <Button Name="WPFRunCleanup" Content="Run System Cleanup" Style="{StaticResource FluentButtonSuccess}" HorizontalAlignment="Left"/>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>

                                <!-- About Content -->
                                <Grid Name="AboutContent" Visibility="Collapsed">
                                        <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="24">
                                                <StackPanel>
                                                        <TextBlock Text="About WDCA" Style="{StaticResource HeaderText}"/>

                                                        <!-- Application Info -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <Grid>
                                                                                <Grid.ColumnDefinitions>
                                                                                        <ColumnDefinition Width="Auto"/>
                                                                                        <ColumnDefinition Width="*"/>
                                                                                </Grid.ColumnDefinitions>

                                                                                <!-- App Icon -->
                                                                                <Border Grid.Column="0" Width="64" Height="64" Background="{StaticResource SystemAccentBrush}" CornerRadius="12" Margin="0,0,20,0">
                                                                                        <TextBlock Text="W" FontSize="32" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                                                                </Border>

                                                                                <!-- App Details -->
                                                                                <StackPanel Grid.Column="1" VerticalAlignment="Center">
                                                                                        <TextBlock Text="Windows Deployment and Configuration Assistant" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource TextPrimaryBrush}" Margin="0,0,0,4"/>
                                                                                        <TextBlock Text="Version 25.01.01" FontSize="14" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,4"/>
                                                                                        <TextBlock Text="© 2025 Tobayashi-san. Licensed under MIT License." FontSize="12" Foreground="{StaticResource TextTertiaryBrush}"/>
                                                                                </StackPanel>
                                                                        </Grid>

                                                                        <Separator Margin="0,20" Background="{StaticResource BorderBrush}"/>

                                                                        <TextBlock Text="A comprehensive PowerShell-based utility with modern WPF interface for streamlining Windows system deployment, configuration, troubleshooting, and cloning operations." TextWrapping="Wrap" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,16"/>

                                                                        <StackPanel Orientation="Horizontal">
                                                                                <Button Name="ViewWiki" Content="Documentation" Style="{StaticResource FluentButton}"/>
                                                                                <Button Name="ReportIssue" Content="Report Issue" Style="{StaticResource FluentButtonSecondary}"/>
                                                                        </StackPanel>
                                                                </StackPanel>
                                                        </Border>

                                                        <!-- System Info -->
                                                        <Border Style="{StaticResource ModernCard}">
                                                                <StackPanel>
                                                                        <TextBlock Text="System Information" Style="{StaticResource SectionHeader}"/>

                                                                        <Grid Margin="0,16,0,0">
                                                                                <Grid.ColumnDefinitions>
                                                                                        <ColumnDefinition Width="150"/>
                                                                                        <ColumnDefinition Width="*"/>
                                                                                </Grid.ColumnDefinitions>
                                                                                <Grid.RowDefinitions>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                        <RowDefinition Height="Auto"/>
                                                                                </Grid.RowDefinitions>

                                                                                <TextBlock Grid.Row="0" Grid.Column="0" Text="Computer Name:" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,8"/>
                                                                                <TextBlock Grid.Row="0" Grid.Column="1" Name="SystemComputerName" Text="COMPUTER-NAME" Foreground="{StaticResource TextPrimaryBrush}" Margin="0,0,0,8"/>

                                                                                <TextBlock Grid.Row="1" Grid.Column="0" Text="PowerShell Version:" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,8"/>
                                                                                <TextBlock Grid.Row="1" Grid.Column="1" Name="PowerShellVersion" Text="5.1.22621.2506" Foreground="{StaticResource TextPrimaryBrush}" Margin="0,0,0,8"/>

                                                                                <TextBlock Grid.Row="2" Grid.Column="0" Text="Admin Rights:" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,8"/>
                                                                                <TextBlock Grid.Row="2" Grid.Column="1" Name="AdminStatus" Text="Yes" Foreground="#FF107C10" Margin="0,0,0,8"/>

                                                                                <TextBlock Grid.Row="3" Grid.Column="0" Text="WinGet Available:" Foreground="{StaticResource TextSecondaryBrush}" Margin="0,0,0,8"/>
                                                                                <TextBlock Grid.Row="3" Grid.Column="1" Name="WinGetStatus" Text="Yes" Foreground="#FF107C10" Margin="0,0,0,8"/>

                                                                                <TextBlock Grid.Row="4" Grid.Column="0" Text="Log File:" Foreground="{StaticResource TextSecondaryBrush}"/>
                                                                                <TextBlock Grid.Row="4" Grid.Column="1" Name="LogFilePath" Text="C:\Temp\WDCA_20250101_120000.log" Foreground="{StaticResource TextSecondaryBrush}"/>
                                                                        </Grid>
                                                                </StackPanel>
                                                        </Border>
                                                </StackPanel>
                                        </ScrollViewer>
                                </Grid>
                        </Grid>

                        <!-- PowerShell Console Panel -->
                        <Grid Grid.Column="2" Name="ConsolePanel" Background="{StaticResource ConsoleBackgroundBrush}" Visibility="Collapsed">
                                <Grid.RowDefinitions>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="*"/>
                                        <RowDefinition Height="Auto"/>
                                </Grid.RowDefinitions>

                                <!-- Console Header -->
                                <Border Grid.Row="0" Background="{StaticResource SurfaceBackgroundBrush}" Padding="12,8" BorderBrush="{StaticResource BorderBrush}" BorderThickness="0,0,0,1">
                                        <Grid>
                                                <Grid.ColumnDefinitions>
                                                        <ColumnDefinition Width="Auto"/>
                                                        <ColumnDefinition Width="*"/>
                                                        <ColumnDefinition Width="Auto"/>
                                                </Grid.ColumnDefinitions>

                                                <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                                                        <Ellipse Width="8" Height="8" Fill="#FF00FF00" Margin="0,0,8,0"/>
                                                        <TextBlock Text="PowerShell Console" FontWeight="SemiBold" FontSize="14" Foreground="{StaticResource TextPrimaryBrush}"/>
                                                </StackPanel>

                                                <TextBlock Grid.Column="1" Name="WPFConsoleStatus" Text="Ready" FontSize="12" Foreground="{StaticResource TextSecondaryBrush}" HorizontalAlignment="Center" VerticalAlignment="Center"/>

                                                <StackPanel Grid.Column="2" Orientation="Horizontal">
                                                        <Button Name="WPFStopConsoleCommand" Content="⏹" Style="{StaticResource FluentButtonSecondary}" Width="30" Height="24" FontSize="12" Margin="0,0,4,0" ToolTip="Stop Current Command"/>
                                                        <Button Name="WPFMinimizeConsole" Content="−" Style="{StaticResource FluentButtonSecondary}" Width="30" Height="24" FontSize="12" ToolTip="Hide Console"/>
                                                </StackPanel>
                                        </Grid>
                                </Border>

                                <!-- Console Output -->
                                <ScrollViewer Grid.Row="1" Name="ConsoleScrollViewer" VerticalScrollBarVisibility="Auto" Padding="0">
                                        <TextBox Name="WPFConsoleOutput" Style="{StaticResource ConsoleTextBox}" IsReadOnly="True" VerticalScrollBarVisibility="Disabled" HorizontalScrollBarVisibility="Auto" AcceptsReturn="True" TextWrapping="Wrap" BorderThickness="0" Text="Windows PowerShell Console&#x0A;Copyright (C) Microsoft Corporation. All rights reserved.&#x0A;&#x0A;PS C:\> "/>
                                </ScrollViewer>

                                <!-- Console Input -->
                                <Grid Grid.Row="2" Margin="8">
                                        <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="Auto"/>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>

                                        <TextBlock Grid.Column="0" Text="PS>" Foreground="{StaticResource ConsoleTextBrush}" FontFamily="Consolas" FontSize="12" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                        <TextBox Grid.Column="1" Name="WPFConsoleInput" Style="{StaticResource ConsoleInput}" BorderThickness="0"/>
                                        <Button Grid.Column="2" Name="WPFExecuteCommand" Content="▶" Style="{StaticResource FluentButton}" Width="32" Height="32" FontSize="14" Margin="8,0,0,0" ToolTip="Execute Command"/>
                                </Grid>
                        </Grid>
                </Grid>

                <!-- Progress Bar -->
                <ProgressBar Grid.Row="2" Name="WPFProgressBar" Style="{StaticResource FluentProgressBar}" Margin="24,0"/>

                <!-- Status Bar -->
                <Border Grid.Row="3" Background="{StaticResource SurfaceBackgroundBrush}" Height="48">
                        <Grid Margin="24,0">
                                <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="*"/>
                                        <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>

                                <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                                        <Ellipse Width="8" Height="8" Fill="#FF107C10" Margin="0,0,8,0"/>
                                        <TextBlock Name="WPFStatusText" Text="Ready - Windows Deployment and Configuration Assistant" Foreground="{StaticResource TextSecondaryBrush}" VerticalAlignment="Center"/>
                                </StackPanel>

                                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                                        <TextBlock Text="v" Foreground="{StaticResource TextTertiaryBrush}"/>
                                        <TextBlock Name="WPFVersionText" Text="25.01.01" Foreground="{StaticResource TextTertiaryBrush}" Margin="2,0,0,0"/>
                                </StackPanel>
                        </Grid>
                </Border>
        </Grid>
</Window>
'@

# Updated scripts/main.ps1 with Integrated Console Support

try {
    Write-Logger "Starting WDCA UI initialization..." "INFO"

    # Check if inputXML exists
    if (-not $inputXML) {
        throw "inputXML variable is not defined or empty"
    }

    # XAML parsing with improved error handling
    try {
        [xml]$XAML = $inputXML
        Write-Logger "XAML parsed successfully" "INFO"

        $reader = (New-Object System.Xml.XmlNodeReader $XAML)
        $global:sync.Form = [Windows.Markup.XamlReader]::Load($reader)

        # Critical Form validation
        if (-not $global:sync.Form) {
            throw "Failed to load XAML - Form is null"
        }

        # Additional Form validation
        if (-not $global:sync.Form.GetType().Name.Contains("Window")) {
            throw "Loaded object is not a Window type"
        }

        Write-Logger "XAML loaded successfully - Form created and validated" "INFO"
    }
    catch [System.Windows.Markup.XamlParseException] {
        Write-Logger "XAML Parse Error: $($_.Exception.Message)" "ERROR"
        Write-Logger "Line: $($_.Exception.LineNumber), Position: $($_.Exception.LinePosition)" "ERROR"
        throw "XAML parsing failed: $($_.Exception.Message)"
    }
    catch {
        Write-Logger "Error loading XAML: $($_.Exception.Message)" "ERROR"
        throw "XAML loading failed: $($_.Exception.Message)"
    }

    # Safely initialize components with error checking
    try {
        Write-Logger "Initializing XAML variables..." "INFO"
        Initialize-WDCAVariables
    }
    catch {
        Write-Logger "Error initializing XAML variables: $($_.Exception.Message)" "ERROR"
    }

    try {
        Write-Logger "Initializing theme manager..." "INFO"
        Initialize-ThemeManager
    }
    catch {
        Write-Logger "Error initializing theme manager: $($_.Exception.Message)" "ERROR"
    }

    try {
        Write-Logger "Applying system theme..." "INFO"
        $systemTheme = Get-SystemThemePreference
        Set-WDCATheme -ThemeName $systemTheme
    }
    catch {
        Write-Logger "Error applying theme: $($_.Exception.Message)" "ERROR"
    }

    try {
        Write-Logger "Initializing window controls..." "INFO"
        Initialize-WindowControls
    }
    catch {
        Write-Logger "Error initializing window controls: $($_.Exception.Message)" "ERROR"
    }

    try {
        Write-Logger "Initializing applications..." "INFO"
        Initialize-WDCAApplications
    }
    catch {
        Write-Logger "Error initializing applications: $($_.Exception.Message)" "ERROR"
    }

    try {
        Write-Logger "Initializing integrated console..." "INFO"
        Initialize-WDCAConsole
    }
    catch {
        Write-Logger "Error initializing console: $($_.Exception.Message)" "ERROR"
    }

    Write-Logger "WDCA UI successfully initialized" "INFO"

    # Initialize navigation
    $currentTab = "Debloat"

    function Show-Content {
        param([string]$TabName)

        try {
            # Hide all content panels
            @("DebloatContent", "ApplicationsContent", "SystemSetupContent", "TroubleshootingContent", "UpdatesContent", "CloningContent", "SettingsContent", "AboutContent") | ForEach-Object {
                if ($sync[$_]) {
                    $sync[$_].Visibility = "Collapsed"
                }
            }

            # Show selected content
            $contentName = "${TabName}Content"
            if ($sync[$contentName]) {
                $sync[$contentName].Visibility = "Visible"
            }

            # Update navigation button states
            @("NavDebloat", "NavApplications", "NavSystemSetup", "NavTroubleshooting", "NavUpdates", "NavCloning", "NavSettings", "NavAbout") | ForEach-Object {
                if ($sync[$_]) {
                    $sync[$_].Tag = ""
                }
            }

            $navButtonName = "Nav$TabName"
            if ($sync[$navButtonName]) {
                $sync[$navButtonName].Tag = "Selected"
            }

            $script:currentTab = $TabName
            Set-WDCAStatus "Switched to $TabName"

            # Load debloat applications when navigating to debloat tab
            if ($TabName -eq "Debloat") {
                Initialize-DebloatApplications
            }
        }
        catch {
            Write-Logger "Error switching to tab ${TabName}: $($_.Exception.Message)" "ERROR"
        }
    }

    # Navigation event handlers with error handling
    if ($sync.NavDebloat) {
        $sync.NavDebloat.Add_Click({
                try {
                    if ((Get-ActiveAsyncOperations).Count -eq 0) {
                        Show-Content "Debloat"
                    }
                    else {
                        [System.Windows.MessageBox]::Show("Please wait for current operation to complete.", "WDCA - Operation in Progress", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
                    }
                }
                catch {
                    Write-Logger "Error in Debloat navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.NavApplications) {
        $sync.NavApplications.Add_Click({
                try {
                    if ((Get-ActiveAsyncOperations).Count -eq 0) {
                        Show-Content "Applications"
                    }
                    else {
                        [System.Windows.MessageBox]::Show("Please wait for current operation to complete.", "WDCA - Operation in Progress", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
                    }
                }
                catch {
                    Write-Logger "Error in Applications navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.NavSystemSetup) {
        $sync.NavSystemSetup.Add_Click({
                try {
                    if ((Get-ActiveAsyncOperations).Count -eq 0) {
                        Show-Content "SystemSetup"
                    }
                    else {
                        [System.Windows.MessageBox]::Show("Please wait for current operation to complete.", "WDCA - Operation in Progress", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
                    }
                }
                catch {
                    Write-Logger "Error in SystemSetup navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.NavTroubleshooting) {
        $sync.NavTroubleshooting.Add_Click({
                try {
                    if ((Get-ActiveAsyncOperations).Count -eq 0) {
                        Show-Content "Troubleshooting"
                    }
                    else {
                        [System.Windows.MessageBox]::Show("Please wait for current operation to complete.", "WDCA - Operation in Progress", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
                    }
                }
                catch {
                    Write-Logger "Error in Troubleshooting navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.NavCloning) {
        $sync.NavCloning.Add_Click({
                try {
                    if ((Get-ActiveAsyncOperations).Count -eq 0) {
                        Show-Content "Cloning"
                    }
                    else {
                        [System.Windows.MessageBox]::Show("Please wait for current operation to complete.", "WDCA - Operation in Progress", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
                    }
                }
                catch {
                    Write-Logger "Error in Cloning navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.NavAbout) {
        $sync.NavAbout.Add_Click({
                try {
                    Show-Content "About"
                }
                catch {
                    Write-Logger "Error in About navigation: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    # Debloat event handlers
    if ($sync.WPFRefreshDebloatList) {
        $sync.WPFRefreshDebloatList.Add_Click({
                try {
                    Write-Logger "Refreshing debloat applications list" "INFO"
                    Initialize-DebloatApplications
                }
                catch {
                    Write-Logger "Error refreshing debloat list: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFUninstallSelected) {
        $sync.WPFUninstallSelected.Add_Click({
                try {
                    Invoke-DebloatUninstall
                }
                catch {
                    Write-Logger "Error in Uninstall Selected: $($_.Exception.Message)" "ERROR"
                }
            })
    }

if ($sync.WPFInstallSelectedApps) {
    $sync.WPFInstallSelectedApps.Add_Click({
        try {
            # Check if any operation is already running
            if ($sync.WPFInstallSelectedApps.Content -like "Installing*" -or
                $sync.WPFUpdateApps.Content -like "Updating*" -or
                $sync.WPFListAppUpdate.Content -like "Checking*") {
                [System.Windows.MessageBox]::Show(
                    "An application operation is already running. Please wait for it to complete.",
                    "WDCA - Operation in Progress",
                    [System.Windows.MessageBoxButton]::OK,
                    [System.Windows.MessageBoxImage]::Information
                )
                return
            }

            Invoke-WPFApplicationsAsync -Mode "Background"
        }
        catch {
            Write-Logger "Error in Install Selected Apps: $($_.Exception.Message)" "ERROR"
        }
    })
}

if ($sync.WPFListAppUpdate) {
    $sync.WPFListAppUpdate.Add_Click({
        try {
            # Check if any operation is already running
            if ($sync.WPFInstallSelectedApps.Content -like "Installing*" -or
                $sync.WPFUpdateApps.Content -like "Updating*" -or
                $sync.WPFListAppUpdate.Content -like "Checking*") {
                [System.Windows.MessageBox]::Show(
                    "An application operation is already running. Please wait for it to complete.",
                    "WDCA - Operation in Progress",
                    [System.Windows.MessageBoxButton]::OK,
                    [System.Windows.MessageBoxImage]::Information
                )
                return
            }

            Invoke-WPFListAppUpdates
        }
        catch {
            Write-Logger "Error in List App Updates: $($_.Exception.Message)" "ERROR"
        }
    })
}

if ($sync.WPFUpdateApps) {
    $sync.WPFUpdateApps.Add_Click({
        try {
            # Check if any operation is already running
            if ($sync.WPFInstallSelectedApps.Content -like "Installing*" -or
                $sync.WPFUpdateApps.Content -like "Updating*" -or
                $sync.WPFListAppUpdate.Content -like "Checking*") {
                [System.Windows.MessageBox]::Show(
                    "An application operation is already running. Please wait for it to complete.",
                    "WDCA - Operation in Progress",
                    [System.Windows.MessageBoxButton]::OK,
                    [System.Windows.MessageBoxImage]::Information
                )
                return
            }

            Invoke-WPFUpdateApps
        }
        catch {
            Write-Logger "Error in Update Apps: $($_.Exception.Message)" "ERROR"
        }
    })
}

    if ($sync.WPFSelectAllApps) {
        $sync.WPFSelectAllApps.Add_Click({
                try {
                    if ($sync.configs.applications) {
                        $sync.configs.applications.PSObject.Properties | ForEach-Object {
                            $checkboxName = $_.Name
                            if ($sync[$checkboxName]) {
                                $sync[$checkboxName].IsChecked = $true
                            }
                        }
                    }
                    Set-WDCAStatus "Selected all applications"
                }
                catch {
                    Write-Logger "Error in Select All Apps: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFDeselectAllApps) {
        $sync.WPFDeselectAllApps.Add_Click({
                try {
                    if ($sync.configs.applications) {
                        $sync.configs.applications.PSObject.Properties | ForEach-Object {
                            $checkboxName = $_.Name
                            if ($sync[$checkboxName]) {
                                $sync[$checkboxName].IsChecked = $false
                            }
                        }
                    }
                    Set-WDCAStatus "Deselected all applications"
                }
                catch {
                    Write-Logger "Error in Deselect All Apps: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    # System Setup event handlers
    if ($sync.WPFConfigureNetwork) {
        $sync.WPFConfigureNetwork.Add_Click({
                try {
                    Invoke-WPFSystemSetup -Action "Network"
                }
                catch {
                    Write-Logger "Error in Configure Network: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFEnableRDP) {
        $sync.WPFEnableRDP.Add_Click({
                try {
                    Invoke-WPFSystemSetup -Action "RDP"
                }
                catch {
                    Write-Logger "Error in Enable RDP: $($_.Exception.Message)" "ERROR"
                }
            })
    }

# Troubleshooting event handlers
    if ($sync.WPFRunDiagnostics) {
        $sync.WPFRunDiagnostics.Add_Click({
                try {
                    Invoke-SystemDiagnosticsAsync
                }
                catch {
                    Write-Logger "Error in Run Diagnostics: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFRunDISM) {
        $sync.WPFRunDISM.Add_Click({
                try {
                    Invoke-SystemTool -Tool "DISM"
                }
                catch {
                    Write-Logger "Error in Run DISM: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFRunSFC) {
        $sync.WPFRunSFC.Add_Click({
                try {
                    Invoke-SystemTool -Tool "SFC"
                }
                catch {
                    Write-Logger "Error in Run SFC: $($_.Exception.Message)" "ERROR"
                }
            })
    }

    if ($sync.WPFRunCHKDSK) {
        $sync.WPFRunCHKDSK.Add_Click({
                try {
                    Invoke-SystemTool -Tool "CHKDSK"
                }
                catch {
                    Write-Logger "Error in Run CHKDSK: $($_.Exception.Message)" "ERROR"
                }
            })
    }

# Cloning event handlers
    if ($sync.WPFRunCleanup) {
        $sync.WPFRunCleanup.Add_Click({
                try {
                    Invoke-PreCloneCleanup
                }
                catch {
                    Write-Logger "Error in Run Cleanup: $($_.Exception.Message)" "ERROR"
                    [System.Windows.MessageBox]::Show(
                        "Error starting cleanup: $($_.Exception.Message)",
                        "WDCA - Cleanup Error",
                        [System.Windows.MessageBoxButton]::OK,
                        [System.Windows.MessageBoxImage]::Error
                    )
                }
            })
    }

    # About page event handlers
    if ($sync.ViewWiki) {
        $sync.ViewWiki.Add_Click({
                try {
                    Write-Logger "Opening WDCA documentation" "INFO"
                    Start-Process "https://github.com/Tobayashi-san/WDCA" -ErrorAction Stop
                }
                catch {
                    Write-Logger "Error opening documentation: $($_.Exception.Message)" "ERROR"
                    [System.Windows.MessageBox]::Show(
                        "Could not open documentation. Please visit:`nhttps://github.com/Tobayashi-san/WDCA/wiki",
                        "WDCA - Documentation",
                        [System.Windows.MessageBoxButton]::OK,
                        [System.Windows.MessageBoxImage]::Information
                    )
                }
            })
    }

    if ($sync.ReportIssue) {
        $sync.ReportIssue.Add_Click({
                try {
                    Write-Logger "Opening issue reporting page" "INFO"
                    Start-Process "https://github.com/Tobayashi-san/WDCA/issues/new" -ErrorAction Stop
                }
                catch {
                    Write-Logger "Error opening issue page: $($_.Exception.Message)" "ERROR"
                    [System.Windows.MessageBox]::Show(
                        "Could not open issue reporting page. Please visit:`nhttps://github.com/Tobayashi-san/WDCA/issues/new",
                        "WDCA - Report Issue",
                        [System.Windows.MessageBoxButton]::OK,
                        [System.Windows.MessageBoxImage]::Information
                    )
                }
            })
    }

    # Update status and version display
    if ($sync.WPFVersionText) {
        $sync.WPFVersionText.Text = "25.01.01"
    }

    if ($sync.PowerShellVersion) {
        $sync.PowerShellVersion.Text = $PSVersionTable.PSVersion.ToString()
    }

if ($sync.WinGetStatus) {
        $hasWinGet = $null -ne (Get-Command winget -ErrorAction SilentlyContinue)
        $sync.WinGetStatus.Text = if ($hasWinGet) { "Yes" } else { "No" }
        $sync.WinGetStatus.Foreground = if ($hasWinGet) { "#FF107C10" } else { "#FFD13438" }
    }

    if ($sync.LogFilePath) {
        $sync.LogFilePath.Text = $sync.logFile
    }

    if ($sync.SystemComputerName) {
        $sync.SystemComputerName.Text = $env:COMPUTERNAME
    }

    Set-WDCAStatus "WDCA initialized and ready"

    # Initialize async operations support
    Initialize-RunspacePool
    $global:ActiveOperations = @{}
    $global:UIStateStack = @()

    # Setup cleanup on window close
    $sync.Form.Add_Closing({
            try {
                Write-Logger "Application closing - cleaning up async operations" "INFO"
                Stop-AllAsyncOperations
                Close-RunspacePool
            }
            catch {
                Write-Logger "Error during window close cleanup: $($_.Exception.Message)" "ERROR"
            }
        })

    # FIXED: Safer exception handler setup
    try {
        $sync.Form.Add_SourceInitialized({
                try {
                    # Check if Dispatcher exists before adding handler
                    if ($sync.Form.Dispatcher -and $sync.Form.Dispatcher.UnhandledException) {
                        $sync.Form.Dispatcher.UnhandledException.Add({
                                param($sender, $e)
                                Write-Logger "Unhandled exception: $($e.Exception.Message)" "ERROR"
                                Stop-AllAsyncOperations
                                $e.Handled = $true
                            })
                    }
                }
                catch {
                    Write-Logger "Could not set up exception handler: $($_.Exception.Message)" "WARNING"
                }
            })
    }
    catch {
        Write-Logger "Error setting up source initialized handler: $($_.Exception.Message)" "WARNING"
    }

    # Set initial content to Debloat
    Show-Content "Debloat"

  # Final validation before showing dialog
    if ($sync.Form -eq $null) {
        throw "Form is null - cannot display window"
    }

    Write-Logger "Showing main window..." "INFO"

    # Show the window with error handling - KORRIGIERTER TEIL
    try {
        # WICHTIG: Verwende [void] um Return-Value zu ignorieren
        [void]$sync.Form.ShowDialog()
    }
    catch [System.Reflection.TargetParameterCountException] {
        Write-Logger "ShowDialog parameter error, trying alternative approach" "WARNING"
        try {
            # Alternative 1: Ohne Parameter und explizite Typkonvertierung
            $dialog = [System.Windows.Window]$sync.Form
            [void]$dialog.ShowDialog()
        }
        catch {
            Write-Logger "Alternative 1 failed, trying Show() method" "WARNING"
            try {
                # Alternative 2: Show() statt ShowDialog()
                $sync.Form.Show()

                # Application-Loop manuell starten
                $app = New-Object System.Windows.Application
                $app.Run()
            }
            catch {
                Write-Logger "All display methods failed: $($_.Exception.Message)" "ERROR"
                throw
            }
        }
    }
    catch [System.InvalidOperationException] {
        Write-Logger "InvalidOperationException during ShowDialog: $($_.Exception.Message)" "ERROR"
        try {
            $sync.Form.Show()
            # Keep application alive with Dispatcher
            [System.Windows.Threading.Dispatcher]::Run()
        }
        catch {
            Write-Logger "Alternative show method also failed: $($_.Exception.Message)" "ERROR"
            throw
        }
    }
    catch {
        Write-Logger "Unexpected error during ShowDialog: $($_.Exception.Message)" "ERROR"

        # Debug-Information sammeln
        Write-Logger "Form Type: $($sync.Form.GetType().FullName)" "DEBUG"
        Write-Logger "Form IsLoaded: $($sync.Form.IsLoaded)" "DEBUG"

        # Letzter Versuch mit expliziter Window-Konvertierung
        try {
            Write-Logger "Trying explicit Window casting..." "INFO"
            $window = [System.Windows.Window]$sync.Form
            $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen
            [void]$window.ShowDialog()
        }
        catch {
            Write-Logger "Explicit casting also failed: $($_.Exception.Message)" "ERROR"
            throw
        }
    }
}
catch {
    Write-Logger "Critical error in main execution: $($_.Exception.Message)" "ERROR"
    Write-Host "Error: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "Stack trace: $($_.ScriptStackTrace)" -ForegroundColor Red

    # Try more detailed error analysis
    if ($_.Exception.InnerException) {
        Write-Host "Inner exception: $($_.Exception.InnerException.Message)" -ForegroundColor Red
    }

    # Form-specific diagnosis
    if ($global:sync.Form) {
        Write-Host "Form status: Exists" -ForegroundColor Yellow
        try {
            Write-Host "Form type: $($global:sync.Form.GetType().FullName)" -ForegroundColor Yellow
            Write-Host "Form IsLoaded: $($global:sync.Form.IsLoaded)" -ForegroundColor Yellow
        }
        catch {
            Write-Host "Cannot get form details: $($_.Exception.Message)" -ForegroundColor Red
        }

        try {
            $sync.Form.Close()
        }
        catch {
            Write-Logger "Error closing form: $($_.Exception.Message)" "ERROR"
        }
    }
    else {
        Write-Host "Form status: NULL" -ForegroundColor Red
    }

    Read-Host "Press Enter to exit"
}
finally {
    # Cleanup async operations
    try {
        Write-Logger "Starting final cleanup..." "INFO"
        Stop-AllAsyncOperations
        Close-RunspacePool
        Close-WDCAConsole
        Write-Logger "Cleanup completed" "INFO"
    }
    catch {
        Write-Logger "Error during cleanup: $($_.Exception.Message)" "ERROR"
    }

    # Clear sync hashtable
    if ($sync) {
        try {
            $sync.Clear()
            Write-Logger "Sync hashtable cleared" "INFO"
        }
        catch {
            Write-Logger "Error clearing sync hashtable: $($_.Exception.Message)" "ERROR"
        }
    }

    Write-Logger "WDCA execution completed" "INFO"
}